&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Adaptability:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;L&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;earn, adjust, and stay effective through change&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;&lt;strong&gt;Connection:&lt;/strong&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;C&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;ommunicat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, collaborat&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;e&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;, and build trust&lt;/span&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotv4sz81zsz68zwz85z3z78zbz88z2z76zpz74z2v1z75zz67zz85zjlvz122zz122z6oaz84z&quot;&gt;.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;To learn more about why these skills matter and what the data shows about thriving through change, read this &lt;/span&gt;&lt;span class=&quot;attrlink url author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt;&lt;a class=&quot;attrlink&quot; href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot; target=&quot;_blank&quot; data-target-href=&quot;https://www.dropbox.jobs/en/our-blog/employee-stories/the-era-of-durable-skills-what-the-data-tells-us-about-thriving-in-change/&quot;&gt;blog post&lt;/a&gt;&lt;/span&gt; &lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotuz85zdz87z113tz83zz67z5n8qpz80zpz89zoz69zcz76zz87zz88zz88z5gsnz85zu&quot;&gt;from&lt;/span&gt;&lt;span class=&quot; author-d-iz88z86z86za0dz67zz78zz78zz74zz68zjz80zz71z9iz90z9z84z5u1z69zz90zlz73z3ly1nz76zw1r5kz89zz66z4z65zz65zjz122zf092&quot;&gt; our Chief People Officer, Melanie Rosenwasser.&lt;/span&gt;&lt;/p&gt;
&lt;h2 data-usually-unique-id=&quot;044234883370604133046166&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz81zqz90zkz74zz76zeez80zz68zz89zz88zvqz86zuxlz73zexxz80zz73z6d6z72zz79zsz77z&quot;&gt;Compensation&lt;/span&gt;&lt;/h2&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;US Zone 1&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;This role is not available in Zone 1&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;US Zone 2&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$172,900&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$233,900 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;US Zone 3&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$153,700&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$207,900 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Discord has a highly engaged community of millions of daily active users who use the platform for many different reasons, but there’s one thing that nearly everyone does: &lt;strong&gt;play video games.&lt;/strong&gt; Discord plays a uniquely important role in the future of gaming, and we are focused on making it easier and more fun for people to hang out before, during, and after playing games.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Discord&#39;s Experimentation Platform puts data at the heart of the company&#39;s decision-making and growth - we run hundreds of experiments at any given time, and those results turn directly into business decisions across Discord.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;As a Staff Data Scientist on this team, you will ensure that the statistical underpinnings of our experiments are sound, that experimenters are able to design experiments with high rigor, and that Discord makes the best business decisions on the basis of these experiments. We are a small and quickly growing team; you will be presented with significant leadership opportunities as we evolve.&lt;/p&gt;
&lt;p&gt;Our team directly impacts the strategy and roadmaps that improve Discord for its more than 90M daily active users! If helping make Discord an even better place to hang out with your friends sounds like an exciting challenge - we&#39;d love to chat with you!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you will be doing&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Formulate the vision and set the roadmap for the future of the Experimentation Platform, in partnership with engineering, product, and data science stakeholders.&lt;/li&gt;
&lt;li&gt;Provide statistical expertise, ensuring that experimentation methodologies and frameworks are sound and aligned with best practices in causal inference and experimental design.&lt;/li&gt;
&lt;li&gt;Partner closely with engineering and product to improve the reliability, scalability, and adoption of experimentation across Discord - including modern AI/LLM tooling where it can accelerate rigor and speed.&lt;/li&gt;
&lt;li&gt;Lead initiatives to educate and train cross-functional teams - including workshops, training sessions, and educational materials - on experimentation design, statistical methodology, and causal inference.&lt;/li&gt;
&lt;li&gt;Empower Discord&#39;s Data Science team (50+ members) to adopt more rigorous causal inference methods.&lt;/li&gt;
&lt;li&gt;Lead and conduct original causal inference research on high-priority Discord questions, in partnership with the wider Data Science team.&lt;/li&gt;
&lt;li&gt;Engage directly with experimentation customers - data scientists, product managers, and engineers - to ensure the platform enables fast, reliable, data-driven decisions.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you should have&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Proven experience leading experimentation platform work, including designing and validating statistical methodologies to ensure the accuracy and reliability of experimental results.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;PhD in a quantitative field (e.g. Statistics, Economics, Political Science, Psychology) or equivalent practical experience, plus 4+ years designing, implementing, and analyzing experiments or causal inference projects.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Ability to critically evaluate and recommend statistical approaches that balance velocity and reliability across a variety of product launches.&lt;/li&gt;
&lt;li&gt;Strong passion for education, with a track record of communicating complex statistical and experimental design concepts to technical and non-technical audiences and fostering a culture of data literacy.&lt;/li&gt;
&lt;li&gt;Demonstrated experience in developing and delivering training programs or educational content related to experimentation, causal inference, or statistical analysis, with a track record of fostering a culture of data literacy within an organization.&lt;/li&gt;
&lt;li&gt;Proficient with Python, SQL, R, and/or other statistical programming languages.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Points&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Interest in conducting literature reviews, translating and championing best scientific practices across the company.&lt;/li&gt;
&lt;li&gt;Track record using causal inference methods that translated into business decisions and outcomes.&lt;/li&gt;
&lt;li&gt;Experience autonomously leading cross-functional projects and influencing cross-functional partners.&lt;/li&gt;
&lt;li&gt;Comfort using AI/LLM tools to accelerate causal inference workflows, automate repetitive analysis, or scale experimentation education content.&lt;/li&gt;
&lt;li&gt;Passion for Discord or gaming.&lt;/li&gt;
&lt;li&gt;Causal inference-related publications.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;San Francisco Bay Area:&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Candidates must reside in or be willing to relocate to the San Francisco Bay Area (Alameda, Contra Costa, Marin, Napa, San Francisco, San Mateo, Santa Clara, Solano, and Sonoma counties). Relocation assistance may be available.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;The US base salary range for this full-time position is $279,000 to $310,000 + equity + benefits. Our salary ranges are determined by role and level. Within the range, individual pay is determined by additional factors, including job-related skills, experience, and relevant education or training. Please note that the compensation details listed in US role postings reflect the base salary only, and do not include equity, or benefits.&lt;/em&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Why Discord?&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;br&gt;Discord plays a uniquely important role in the future of gaming. We&#39;re a multiplatform, multigenerational and multiplayer platform that helps people deepen their friendships around games and shared interests, and helps developers build and grow their businesses. We believe games give us a way to have fun with our favorite people, whether listening to music together or grinding in competitive matches for diamond rank. &lt;strong&gt;Join us in our mission! Your future is just a click away!&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Discord is committed to inclusion and providing reasonable accommodations during the interview process. &lt;/strong&gt;We want you to feel set up for success, so if you are in need of reasonable accommodations, please let your recruiter know.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;strong&gt;Please see our Applicant and Candidate Privacy Policy for details regarding Discord’s collection and usage of personal information relating to the application and recruitment process by clicking&amp;nbsp;&lt;a href=&quot;https://discord.com/terms/applicant-candidate-privacy-policy&quot;&gt;HERE.&lt;/a&gt;&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;p&gt;&lt;strong&gt;AI Engineer – Forward Deployed Engineering (AI FDE) (ALL LEVELS)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;CSQ327R177&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Mission&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The AI Forward Deployed Engineering (AI FDE) team is a highly specialized customer-facing AI team at Databricks. We deliver professional services engagements to help our customers build and productionize first-of-its-kind AI applications. We work cross-functionally to shape long-term strategic priorities and initiatives alongside engineering, product, and developer relations, as well as support internal subject matter expert (SME) teams. We view our team as an ensemble: we look for individuals with strong, unique specializations to improve the overall strength of the team. This team is the right fit for you if you love working with customers, teammates, and fueling your curiosity for the latest trends in GenAI, LLMOps, and ML more broadly. Open to remote locations.&lt;/p&gt;
&lt;p&gt;This role is intended for experienced engineers with demonstrated industry experience designing, building, and deploying production GenAI and LLM applications at scale. It is not intended for internship, new graduate, or entry-level applicants.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The impact you will have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Develop cutting-edge GenAI solutions, incorporating the latest techniques from &lt;a href=&quot;https://www.databricks.com/blog/category/databricks-ai?categories=databricks-ai%2Cai-research%2Cai-engineering&quot;&gt;Databricks AI research&lt;/a&gt; to solve customer problems&lt;/li&gt;
&lt;li&gt;Own production rollouts of consumer and internally facing GenAI applications&lt;/li&gt;
&lt;li&gt;Serve as a trusted technical advisor to customers across a variety of domains&lt;/li&gt;
&lt;li&gt;Present at conferences such as &lt;a href=&quot;https://www.databricks.com/dataaisummit&quot;&gt;Data + AI Summit&lt;/a&gt;, recognized as a thought leader internally and externally&lt;/li&gt;
&lt;li&gt;Collaborate cross-functionally with the product and engineering teams to influence priorities and shape the product roadmap&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What we look for:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience building GenAI applications, including RAG, multi-agent systems, Text2SQL, fine-tuning, etc., with tools such as HuggingFace, LangChain, and DSPy&lt;/li&gt;
&lt;li&gt;Expertise in deploying production-grade GenAI applications, including evaluation and optimizations&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Extensive years of hands-on industry data science experience, leveraging common machine learning and data science tools, i.e. pandas, scikit-learn, PyTorch, etc.&lt;/li&gt;
&lt;li&gt;Experience building production-grade machine learning deployments on AWS, Azure, or GCP&lt;/li&gt;
&lt;li&gt;Graduate degree in a quantitative discipline (Computer Science, Engineering, Statistics, Operations Research, etc.) or equivalent practical experience&lt;/li&gt;
&lt;li&gt;Experience communicating and/or teaching technical concepts to non-technical and technical audiences alike&lt;/li&gt;
&lt;li&gt;Passion for collaboration, life-long learning, and driving business value through AI&lt;/li&gt;
&lt;li&gt;[Preferred] Experience using the Databricks Intelligence Platform and Apache Spark™ to process large-scale distributed datasets&lt;/li&gt;
&lt;li&gt;Willing to travel once every 4-8 weeks to see customers (as needed)&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Pay Range Transparency&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400; font-size: 14px;&quot;&gt;Databricks is committed to fair and equitable compensation practices. The pay range(s) for this role is listed below and represents the expected salary range for non-commissionable roles or on-target earnings for commissionable roles.&amp;nbsp; Actual compensation packages are based on several factors that are unique to each candidate, including but not limited to job-related skills, depth of experience, relevant certifications and training, and specific work location. Based on the factors above, Databricks anticipates utilizing the full width of the range. The total compensation package for this position may also include eligibility for annual performance bonus, equity, and the benefits listed above. For more information regarding which range your location is in visit our page &lt;a href=&quot;https://www.databricks.com/sites/default/files/2024-08/us-pay-zone-mapping.pdf&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Local Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$152,900&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$210,155 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Databricks&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;Databricks is the Data and AI company. More than 20,000 organizations worldwide — including adidas, AT&amp;amp;T, Bayer, Block, Mastercard, Rivian, Unilever, and 70% of the Fortune 500 — rely on the Databricks Data + AI Platform to build and scale data and AI apps, analytics and agents. Headquartered in San Francisco with 30+ offices around the globe, Databricks offers a unified platform that includes Genie, Lakebase, Agent Bricks, Lakeflow, Lakehouse, and Unity Catalog. To learn more, follow Databricks on &lt;a href=&quot;https://www.linkedin.com/company/databricks&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://x.com/databricks&quot;&gt;X&lt;/a&gt;, &lt;a href=&quot;https://www.youtube.com/@Databricks&quot;&gt;YouTube&lt;/a&gt;, and &lt;a href=&quot;https://www.instagram.com/databricksinc/?hl=en&quot;&gt;Instagram&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Benefits&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;At Databricks, we strive to provide comprehensive benefits and perks that meet the needs of all of our employees. For specific details on the benefits offered in your region click &lt;a href=&quot;https://docs.google.com/document/d/154un3e8Xav4BceOSlcYFZRGEuQI54xMxVydRwQn54eQ/edit?usp=sharing&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Diversity and Inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Databricks, we are committed to fostering a diverse and inclusive culture where everyone can excel. We take great care to ensure that our hiring practices are inclusive and meet equal employment opportunity standards. Individuals looking for employment at Databricks are considered without regard to age, color, disability, ethnicity, family or marital status, gender identity or expression, language, national origin, physical and mental ability, political affiliation, race, religion, sexual orientation, socio-economic status, veteran status, and other protected characteristics.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Compliance&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If access to export-controlled technology or source code is required for performance of job duties, it is within Employer&#39;s discretion whether to apply for a U.S. government license for such positions, and Employer may decline to proceed with an applicant on this basis alone.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;At Affirm, we exist for the moments that matter—giving people a clear, predictable way to pay over time, with no hidden fees, no surprises, and no tradeoffs on what matters most.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;
&lt;p&gt;Consumers across the globe need safe, transparent financing while merchants want to provide users with their preferred way to pay and convert more buyers. To help achieve this vision, we are hiring a &lt;strong&gt;Senior Product Manager&lt;/strong&gt; for our &lt;strong&gt;1:Many Growth&lt;/strong&gt; team.&lt;/p&gt;
&lt;p&gt;Affirm&#39;s Distribution Partnerships program - internally called &quot;&lt;strong&gt;1:Many&lt;/strong&gt;&quot; - is one of the highest-leverage growth levers at the company. Instead of integrating merchant by merchant, we integrate once into a platform merchants already use, and every merchant on that platform becomes reachable through that single integration. This role is responsible for:&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Own and grow Affirm&#39;s partner portfolio&lt;/strong&gt;&amp;nbsp;- making it easier and more frictionless for merchants to onboard and offer Affirm as a payment method to their customers. This includes taking product ownership of Affirm&#39;s existing vertical software partnerships, and growing the broader portfolio of platform partners still being stood up.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Partner Acceleration Strategy&lt;/strong&gt;&amp;nbsp;- building the durable capabilities that make every future partner integration faster to launch and easier to scale, rather than solving the same problem one partner at a time.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;As a Senior Product Manager, you will work closely with cross-functional teams including commercial, merchant risk, design, product analytics, and engineering to define, launch and grow integrations with platform partners. Effective stakeholder management and ability to successfully navigate organizational dynamics are a must for success. You should be outcomes-driven with a very high bias for action.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You&#39;ll Do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Collaborate with cross-functional teams to define, launch, and grow integrations with payment and platform partners.&lt;/li&gt;
&lt;li&gt;Build durable, repeatable capabilities through a Partner Acceleration Strategy that makes future partner integrations faster to launch.&lt;/li&gt;
&lt;li&gt;Build relationships with platform partners to gather feedback and insights on product performance, and use it to drive merchant growth.&lt;/li&gt;
&lt;li&gt;Define and prioritize product features and requirements to improve the customer, partner, and merchant experience.&lt;/li&gt;
&lt;li&gt;Create and manage the product roadmap for the broader 1:Many growth team.&lt;/li&gt;
&lt;li&gt;Develop success metrics/OKRs to measure the effectiveness of these initiatives.&lt;/li&gt;
&lt;li&gt;Partner with commercial and product marketing teams to develop go-to-market strategies for new partner integrations and features.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What We Look For&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of product management experience&lt;/li&gt;
&lt;li&gt;Proven ability to multiple technical software products from kickoff to post-launch, driving meaningful business impact you can clearly articulate.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Skilled in cross-functional collaboration — diving into technical details with engineers, iterating with designers in Figma, and analyzing funnel performance with data analysts.&lt;/li&gt;
&lt;li&gt;Strong organizational and communication skills to navigate complex dynamics and drive alignment.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Execution-oriented with a proactive approach to overcoming obstacles and blockers.&lt;/li&gt;
&lt;li&gt;Adept at transforming incomplete or conflicting inputs into clear, actionable plans.&lt;/li&gt;
&lt;li&gt;Demonstrated track record of shipping high-quality products on time.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Comfortable engaging in the commercial aspects of product development, including representing the product externally, setting expectations, and influencing outcomes that benefit both Affirm and its partners.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Bonus points: Experience in Fintech, Lending, ecommerce, or BNPL.&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;p&gt;&lt;br&gt;&lt;br&gt;Pay Grade - N&lt;br&gt;Equity Grade - 9&lt;/p&gt;
&lt;p&gt;&lt;br&gt;Employees new to Affirm typically come in at the start of the pay range. Affirm focuses on providing a simple and transparent pay structure which is based on a variety of factors, including location, experience and job-related skills.&lt;br&gt;&lt;br&gt;Base pay is part of a total compensation package that may include equity rewards, monthly stipends for health, wellness and tech spending, and benefits (including 100% subsidized medical coverage, dental and vision for you and your dependents.)&lt;br&gt;&lt;br&gt;USA base pay range (CA, WA, NY, NJ, CT) per year: $195,000 - $255,000&lt;br&gt;USA base pay range (all other U.S. states) per year: $173,000 - $233,000&lt;br&gt;&lt;br&gt;&lt;br&gt;#LI-Remote&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;
&lt;p&gt;&lt;strong&gt;Remote-first with flexibility built in&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;Affirm is proud to be a remote-first company. Most roles can be done from almost anywhere within the country of employment. Some positions may occasionally require in-person work at an Affirm office, and a few are office-based due to the nature of the work. All new hires will be invited to attend an in-person onboarding experience.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefits designed for you&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;Our benefits reflect our commitment to care, transparency, and flexibility. Here are a few highlights:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Health coverage at no cost: We cover 100% of premiums for employees and their dependents.&lt;/li&gt;
&lt;li&gt;Spending stipends: Monthly stipends support your tech setup, and the ability to choose health and wellness options that are right for you.&lt;/li&gt;
&lt;li&gt;Time off to recharge: Flexible time off and generous holiday calendars help you rest when you need to.&lt;/li&gt;
&lt;li&gt;Own a piece of what you build: Our employee stock purchase plan (ESPP) lets you buy Affirm stock at a discount.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;We’re committed to providing an inclusive interview process, including accommodations for candidates with disabilities. If you need support, we’re happy to help.&lt;/p&gt;
&lt;p&gt;For positions based in San Francisco or Los Angeles: Affirm considers qualified applicants with arrest and conviction records, as required by law.&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;p&gt;By clicking &quot;Submit Application,&quot; you acknowledge that you have read Affirm&#39;s&amp;nbsp;&lt;a href=&quot;https://www.affirm.com/global-candidate-privacy-notice&quot; target=&quot;_blank&quot;&gt;Global Candidate Privacy Notice&lt;/a&gt; and consent to the use of your personal information as described.&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;GitLab is the intelligent orchestration platform for DevSecOps. GitLab enables organizations to increase developer productivity, improve operational efficiency, reduce security and compliance risk, and accelerate digital transformation. More than 50 million registered users and more than 50% of the Fortune 100* trust GitLab to ship better, more secure software faster.&lt;/p&gt;
&lt;p&gt;The same principles built into our products are reflected in how our team works: we embrace AI as a core productivity multiplier, with all team members expected to incorporate AI into their daily workflows to drive efficiency, innovation, and impact. GitLab is where careers accelerate, innovation flourishes, and every voice is valued. Our high-performance culture is driven by our values&amp;nbsp;and continuous knowledge exchange, enabling our team members to reach their full potential while collaborating with industry leaders to solve complex problems. &lt;a href=&quot;https://www.youtube.com/watch?v=OuZIb5zszQI&quot;&gt;Co-create the future with us&lt;/a&gt; as we build technology that transforms how the world develops software.&lt;/p&gt;
&lt;p&gt;*&lt;em&gt;Fortune 500® is a registered trademark of Fortune Media IP Limited, used under license. Claim based on GitLab data. Fortune 100 refers to the top 20% ranked companies in the 2025 Fortune 500 list, published in June 2025. Fortune and Fortune Media IP Limited are not affiliated with, and do not endorse products or services of GitLab.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;&lt;strong&gt;An overview of this role&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;As an Senior AI Engineer at GitLab, you&#39;ll help build the foundation for GitLab&#39;s transformation into an AI-first company. Reporting to the Director, Enterprise AI, you&#39;ll be a hands-on technical leader responsible for delivering internal AI-powered solutions that drive measurable business outcomes.&lt;/p&gt;
&lt;p&gt;Building fast matters, but it&#39;s not enough on its own. This role starts with understanding the real problem: mapping how work moves across teams, tools, and handoffs, identifying the true constraint, and validating whether AI is the right solution before you begin development. From there, you&#39;ll take ownership from discovery through deployment, combining strong engineering skills with systems thinking and business understanding.&lt;/p&gt;
&lt;p&gt;Your initial focus will span Sales, Marketing, and Customer Support, where you will embed AI solutions into key systems and workflows. This role offers the opportunity to shape how GitLab team members work, improve flow across the organization, and help advance our mission in a remote, asynchronous, and values-driven environment.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;What you&#39;ll do&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Diagnose business problems before building solutions. Map workflows, identify constraints, and confirm whether AI is the right intervention. Be prepared to say &quot;this doesn&#39;t need AI&quot; when that&#39;s the honest answer.&lt;/li&gt;
&lt;li&gt;Own AI initiatives end-to-end, from stakeholder discovery and technical design through implementation, deployment, and iteration.&lt;/li&gt;
&lt;li&gt;Design, develop, and ship AI-powered solutions quickly, delivering working prototypes in days, not months, with a focus on practical outcomes and measurable business value.&lt;/li&gt;
&lt;li&gt;Improve organizational flow by building solutions that reduce bottlenecks, shorten lead times, and increase throughput. Measure success using flow metrics alongside adoption and ROI.&lt;/li&gt;
&lt;li&gt;Integrate AI capabilities into existing systems and workflows using APIs, orchestration tools, and modern AI platforms, including GitLab Duo Agent Platform, where appropriate. The right tool wins, whether that&#39;s custom code, a platform, or a well-crafted prompt.&lt;/li&gt;
&lt;li&gt;Be Customer Zero: leverage and showcase GitLab&#39;s AI offerings wherever possible, feeding real-world usage insights back to R&amp;amp;D.&lt;/li&gt;
&lt;li&gt;Partner closely with stakeholders across functions to understand the real constraints. Ask the right questions, bridge technical and non-technical perspectives, and align on outcomes before jumping to solutions.&lt;/li&gt;
&lt;li&gt;Define and track success through business metrics, flow metrics, and feedback loops that make performance visible and actionable.&lt;/li&gt;
&lt;li&gt;Contribute to technical direction by evaluating tools, documenting patterns, and creating reusable foundations that help the team scale its impact.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;What you&#39;ll bring&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;A Technologist at Heart -&amp;nbsp;&lt;/strong&gt;Genuinely invested in technology, the foundational and the cutting-edge in equal measure. You&#39;re as energised by a well-designed API integration as you are by the latest foundation model release. You reach for the simplest solution that solves the problem well, rather than forcing new technology when proven approaches would do. AI is a powerful part of your toolkit, but it sits on top of solid engineering fundamentals, not in place of them.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Competent, Confident Coding Skills -&amp;nbsp;&lt;/strong&gt;You can build working solutions end-to-end, write clean and maintainable code, and debug effectively. Whether your skills were honed in a traditional engineering role, through building automations, or shipping side projects, what matters is that you can deliver production-quality work independently.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&amp;amp; LLM&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;Technical Depth -&amp;nbsp;&lt;/strong&gt;Strong proficiency in at least one modern scripting language (Python, JavaScript/TypeScript, or similar) and a solid understanding of REST APIs, GraphQL, and integration patterns. Deep, practical experience with modern AI technologies, specifically:&amp;nbsp;Prompt engineering as a core discipline: designing effective system prompts, managing context windows, structuring multi-turn interactions, evaluating output quality, and iterating systematically on prompt design.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Model selection and cost-performance trade-offs:&amp;nbsp;&lt;/strong&gt;understanding when a smaller fine-tuned model outperforms a general-purpose large one, when RAG is the right architecture versus expanding the context window, and how to make principled decisions about capability versus cost.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Agentic architecture patterns:&amp;nbsp;&lt;/strong&gt;tool use, multi-agent orchestration, human-in-the-loop designs, guardrails, evaluation frameworks, and production-grade reliability patterns.Practical fluency across the LLM ecosystem: hands-on experience with models from Anthropic, OpenAI, open-source alternatives, and the judgment to know which to reach for and when.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI Safety &amp;amp; Risk Awareness -&amp;nbsp;&lt;/strong&gt;You think critically about how the solutions you build could be exploited, misused, or produce unintended consequences. You know how to design appropriate guardrails (input validation, output filtering, access controls, prompt injection defences, and data leakage prevention) and you treat these as first-class engineering concerns.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Systems Thinking &amp;amp; Diagnostic Rigour -&amp;nbsp;&lt;/strong&gt;The ability to look at a complex process and see the constraint. Comfortable mapping how work flows end-to-end, identifying bottlenecks, and tracing problems to root causes before proposing solutions. You instinctively ask &quot;what&#39;s actually blocking flow here?&quot; before asking &quot;what model should I use?&quot;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Business System Expertise -&amp;nbsp;&lt;/strong&gt;Familiarity with the landscape of enterprise business systems, CRM (Salesforce), marketing automation (Marketo), support platforms (Zendesk), integration and orchestration tools (Workato), AI platforms (Relevance AI), and enterprise search and knowledge tools (Glean). You don&#39;t need deep experience with all of these, but to understand what they do, how they fit together, and be willing to build with and across them. A strong understanding of enterprise data models and workflows is essential.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Broad Functional Understanding -&amp;nbsp;&lt;/strong&gt;Ability to have meaningful conversations with stakeholders across diverse domains and quickly understand their unique needs.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;End-to-End Ownership -&amp;nbsp;&lt;/strong&gt;Track record of owning complex initiatives from discovery through delivery. Comfortable operating with ambiguity and driving to measurable outcomes independently.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Product Mindset -&amp;nbsp;&lt;/strong&gt;Ability to scope MVPs, prioritise ruthlessly, and deliver iteratively. In addition, consider adoption, user experience, and business outcomes.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Preferred requirements&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience with GitLab platform and CI/CD workflows&lt;/li&gt;
&lt;li&gt;Background in consulting, solutions engineering, or customer-facing technical roles&lt;/li&gt;
&lt;li&gt;Familiarity with value stream mapping, flow metrics, or Theory of Constraints thinking&lt;/li&gt;
&lt;li&gt;Experience with low-code/no-code orchestration tools (n8n, Make, Workato) alongside custom development&lt;/li&gt;
&lt;li&gt;Previous startup or high-growth company experience&lt;/li&gt;
&lt;li&gt;Experience mentoring or leading technical projects with junior engineers&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;About the team&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;You will join the&amp;nbsp;Enterprise Technology &amp;amp; AI&amp;nbsp;team. We&#39;re the backbone of the organisation, driving transformation in how GitLab team members make decisions, operate at scale, and deliver results for our customers.&lt;/p&gt;
&lt;p&gt;We believe the best AI solutions start with understanding the system, not the technology. We value people who think in constraints and flow, who build with conviction, and who never stop learning. We work in an all-remote, asynchronous setting, guided by GitLab&#39;s values of collaboration, results, efficiency, diversity, inclusion and belonging, iteration, and transparency.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;em&gt;The base salary range for this role’s listed level is currently for residents of the&amp;nbsp;United States only. This range is intended to reflect the role&#39;s base salary rate in locations throughout the US.&amp;nbsp;Grade level and salary ranges are determined through interviews and a review of education, experience, knowledge, skills, abilities of the applicant, equity with other team members, alignment with market data,&amp;nbsp;and geographic location.&amp;nbsp;The base salary range does not include any bonuses, equity, or benefits. See more information on our &lt;a class=&quot;waffle-rich-text-link&quot; href=&quot;https://about.gitlab.com/handbook/total-rewards/benefits/general-and-entity-benefits/&quot; data-sheets-formula-bar-text-link=&quot;https://bit.ly/GLBeneUS&quot; data-sheets-formula-bar-text-style=&quot;font-size:12px;color:#1155cc;font-weight:normal;text-decoration:underline;font-family:&#39;&#39;Arial&#39;&#39;;font-style:normal;text-decoration-skip-ink:none;&quot;&gt;benefits&lt;/a&gt;&lt;span data-sheets-formula-bar-text-style=&quot;font-size:12px;color:#000000;font-weight:normal;text-decoration:none;font-family:&#39;Arial&#39;;font-style:normal;text-decoration-skip-ink:none;&quot;&gt; and &lt;/span&gt;&lt;a class=&quot;waffle-rich-text-link&quot; href=&quot;https://about.gitlab.com/handbook/stock-options/&quot; data-sheets-formula-bar-text-link=&quot;https://bit.ly/GLequity&quot; data-sheets-formula-bar-text-style=&quot;font-size:12px;color:#1155cc;font-weight:normal;text-decoration:underline;font-family:&#39;&#39;Arial&#39;&#39;;font-style:normal;text-decoration-skip-ink:none;&quot;&gt;equity&lt;/a&gt;. Sales roles are also eligible for incentive pay targeted at up to 100% of the offered base salary.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;United States Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$108,400&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$129,600 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h4&gt;&lt;strong&gt;How GitLab Supports Full-Time Employees&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/total-rewards/benefits/general-and-entity-benefits/&quot;&gt;Benefits to support your health, finances, and well-being&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://handbook.gitlab.com/handbook/people-group/time-off-and-absence/time-off-types/#flexible-paid-time-off-pto&quot;&gt;Flexible Paid Time Off&amp;nbsp;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://handbook.gitlab.com/handbook/company/culture/inclusion/tmrg-tmag/&quot;&gt;Team Member Resource Groups&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://handbook.gitlab.com/handbook/total-rewards/stock-options/&quot;&gt;Equity Compensation &amp;amp; Employee Stock Purchase Plan&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://handbook.gitlab.com/handbook/people-group/learning-and-development/growth-and-development/&quot;&gt;Growth and Development Fund&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/total-rewards/benefits/general-and-entity-benefits/#parental-leave&quot;&gt;Parental Leave&lt;/a&gt;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Please note that we welcome interest from candidates with varying levels of experience; many successful candidates do not meet every single requirement. Additionally, studies have shown that people from &lt;a href=&quot;https://about.gitlab.com/company/culture/inclusion/#examples-of-select-underrepresented-groups&quot;&gt;underrepresented groups&lt;/a&gt; are less likely to apply to a job unless they meet every single qualification. If you&#39;re excited about this role, please apply and allow our recruiters to assess your application.&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&lt;strong&gt;Country Hiring Guidelines: &lt;/strong&gt;GitLab hires new team members in countries around the world. All of our roles are remote, however some roles may carry specific location-based eligibility requirements. Our Talent Acquisition team can help answer any questions about location after starting the recruiting process.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Privacy Policy: &lt;/strong&gt;Please review our &lt;a href=&quot;https://handbook.gitlab.com/handbook/hiring/candidate-faq/recruitment-privacy-policy/&quot; target=&quot;_blank&quot;&gt;Recruitment Privacy Policy.&lt;/a&gt; Your privacy is important to us.&lt;/p&gt;
&lt;p&gt;GitLab is proud to be an equal opportunity workplace and is an affirmative action employer. GitLab’s policies and practices relating to recruitment, employment, career development and advancement, promotion, and retirement are based solely on merit, regardless of race, color, religion, ancestry, sex (including pregnancy, lactation, sexual orientation, gender identity, or gender expression), national origin, age, citizenship, marital status, mental or physical disability, genetic information (including family medical history), discharge status from the military, protected veteran status (which includes disabled veterans, recently separated veterans, active duty wartime or campaign badge veterans, and Armed Forces service medal veterans), or any other basis protected by law. GitLab will not tolerate discrimination or harassment based on any of these characteristics. See also&amp;nbsp;&lt;a href=&quot;https://about.gitlab.com/handbook/people-policies/inc-usa/#equal-employment-opportunity-policy&quot; target=&quot;_blank&quot;&gt;GitLab’s EEO Policy&lt;/a&gt;&amp;nbsp;and&amp;nbsp;&lt;a href=&quot;https://about.gitlab.com/handbook/labor-and-employment-notices/#eeoc-us-equal-employment-opportunity-commission-notices&quot; target=&quot;_blank&quot;&gt;EEO is the Law&lt;/a&gt;. If you have a disability or special need that requires&amp;nbsp;&lt;a href=&quot;https://about.gitlab.com/handbook/people-policies/inc-usa/#reasonable-accommodation&quot; target=&quot;_blank&quot;&gt;accommodation&lt;/a&gt;, please let us know during the&amp;nbsp;&lt;a href=&quot;https://about.gitlab.com/handbook/hiring/interviewing/#adjustments-to-our-interview-process&quot; target=&quot;_blank&quot;&gt;recruiting process&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Arize&lt;/h3&gt;
&lt;p&gt;AI is rapidly transforming the world. As generative AI reshapes industries, teams need powerful ways to monitor, troubleshoot, and optimize their AI systems. That’s where we come in. &lt;strong data-stringify-type=&quot;bold&quot;&gt;Arize AI is the leading AI &amp;amp; Agent Engineering observability and evaluation platform&lt;/strong&gt;, empowering AI engineers to ship high-performing, reliable agents and applications. From first prototype to production scale, Arize AX unifies build, test, and run in a single workspace—so teams can ship faster with confidence.&lt;/p&gt;
&lt;p&gt;We’re a &lt;strong data-stringify-type=&quot;bold&quot;&gt;Series C&lt;/strong&gt;&amp;nbsp;company backed by top-tier investors,&lt;strong data-stringify-type=&quot;bold&quot;&gt;&amp;nbsp;&lt;/strong&gt;with&lt;strong data-stringify-type=&quot;bold&quot;&gt;&amp;nbsp;over $135M in funding&lt;/strong&gt;&amp;nbsp;and a rapidly growing customer base of&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;150+ leading enterprises and Fortune 500 companies.&amp;nbsp;&lt;/strong&gt;Customers like&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;http://booking.com/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;http://Booking.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;Booking.com&lt;/a&gt;, Uber, Siemens, and PepsiCo leverage Arize to deliver AI that works.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;The Opportunity&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;AI is rapidly transforming the world. Whether it’s developing the next generation of human-level intelligence, enhancing voice assistants, or enabling researchers to analyze genetic markers at scale, AI is increasingly integrated into various aspects of our daily lives.&lt;/p&gt;
&lt;p&gt;Arize AI is the leading AI observability and evaluation platform, empowering AI engineers to build and deploy high-performing, reliable models. As the AI landscape shifts from traditional ML to generative AI and agentic systems, Arize ensures teams have the tools to monitor, troubleshoot, and improve AI in production.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Team&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our team is working to define the “canonical stack” for AI workflows, by solving the toughest problems in AI today: how to experiment, evaluate, understand and improve models or applications at scale in a responsible way. The product team has deep technical and strategic backgrounds from leading AI/ML companies (Uber, Cruise, Spotify, Apple) and experience shipping market leading platforms at scale. Working with this team is an opportunity to develop further as a PM leader in a rapidly growing space by collaborating with some of the best in class AI Engineers and Data Scientists in the industry.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You will be owning, strategizing, and developing a large portion of Arize AI’s core product roadmap.&lt;/li&gt;
&lt;li&gt;From ideation to creation, you will be involved in all stages of the product life cycle.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You will be engaging with our customers directly to gather meaningful insight and feedback in order to create a world class product.&lt;/li&gt;
&lt;li&gt;You will be working cross functionally with internal and external stakeholders; including engineering, design, marketing, and sales to drive our product strategy into production.&lt;/li&gt;
&lt;li&gt;You will be responsible for communicating and integrating competitive analysis, usability research, and market analysis into product requirements.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Utilize your understanding in AI/ML/CV or related technical space in order to contribute to Arize AI’s main product offering.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What We’re Looking For&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;3-5+ years of relevant product management experience or previous AI/ML experience with strong product ownership in an AI-native company&lt;/li&gt;
&lt;li&gt;Previous engineering and/or tech lead experience&lt;/li&gt;
&lt;li&gt;Strong track record of building in a technical domain while shipping quickly and efficiently.&lt;/li&gt;
&lt;li&gt;Willingness to get your hands dirty with code!&lt;/li&gt;
&lt;li&gt;Experience and/or knowledge of working within machine learning, or data platforms and infrastructure.&lt;/li&gt;
&lt;li&gt;Experience working directly with customers and promoting community discussions in order to gather client feedback.&lt;/li&gt;
&lt;li&gt;Experience driving data-informed product strategy into production.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Points, But Not Required&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience in API design&lt;/li&gt;
&lt;li&gt;Early startup experience&lt;/li&gt;
&lt;li&gt;Experience working with Figma or similar design tools&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The estimated annual salary for this role is between $200,000-$250,000, plus a competitive equity package. Actual compensation is determined based upon a variety of job related factors that may include: transferable work experience, skill sets, and qualifications. Total compensation also includes a comprehensive benefit package, including: medical, dental, vision, 401(k) plan, unlimited paid time off, generous parental leave plan, and others for mental and wellness support.&lt;/p&gt;
&lt;p&gt;While we are a remote-first company, we have opened offices in New York City and the San Francisco Bay Area, as an option for those in those cities who wish to work in-person. For all other employees, there is a WFH monthly stipend to pay for co-working spaces.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;More About Arize&lt;/h3&gt;
&lt;p&gt;Arize’s mission is to make the world’s AI work—and work for people.&lt;br&gt;Our founders came together through a shared frustration: while investments in AI are growing rapidly across every industry, organizations face a critical challenge—understanding whether AI is performing and how to improve it at scale.&lt;/p&gt;
&lt;p&gt;Learn more about what we&#39;re doing here:&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://techcrunch.com/2025/02/20/arize-ai-hopes-it-has-first-mover-advantage-in-ai-observability/&quot;&gt;https://techcrunch.com/2025/02/20/arize-ai-hopes-it-has-first-mover-advantage-in-ai-observability/&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://arize.com/blog/arize-ai-raises-70m-series-c-to-build-the-gold-standard-for-ai-evaluation-observability/&quot;&gt;https://arize.com/blog/arize-ai-raises-70m-series-c-to-build-the-gold-standard-for-ai-evaluation-observability/&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Diversity &amp;amp; Inclusion @ Arize&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our company&#39;s mission is to make AI work and make AI work for the people, we hope to make an impact in bias industry-wide and that&#39;s a big motivator for people who work here. We actively hope that individuals contribute to a good culture&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Regularly have chats with industry experts, researchers, and ethicists across the ecosystem to advance the use of responsible AI&lt;/li&gt;
&lt;li&gt;Culturally conscious events such as LGBTQ trivia during pride month&lt;/li&gt;
&lt;li&gt;We have an active Lady Arizers subgroup&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;

&lt;div class=&quot;ng-tns-c879422873-771&quot;&gt;
&lt;section id=&quot;processing-state-26&quot; class=&quot;processing-state_container ng-tns-c879422873-771 is-gpi-avatar is-done-processing ng-trigger ng-trigger-processingStateShowHide ng-star-inserted&quot;&gt;
&lt;div id=&quot;processing-state-26-summary&quot; class=&quot;processing-state_details ng-trigger ng-trigger-menuExpansion ng-tns-c879422873-771 is-gpi-avatar ng-star-inserted&quot;&gt;
&lt;div class=&quot;ng-tns-c879422873-771&quot;&gt;
&lt;section id=&quot;processing-state-26&quot; class=&quot;processing-state_container ng-tns-c879422873-771 is-gpi-avatar is-done-processing ng-trigger ng-trigger-processingStateShowHide ng-star-inserted&quot;&gt;
&lt;div id=&quot;processing-state-26-summary&quot; class=&quot;processing-state_details ng-trigger ng-trigger-menuExpansion ng-tns-c879422873-771 is-gpi-avatar ng-star-inserted&quot;&gt;
&lt;h4&gt;&lt;strong&gt;About commercetools&lt;/strong&gt;&lt;/h4&gt;
&lt;/div&gt;
&lt;/section&gt;
&lt;/div&gt;
&lt;div class=&quot;response-content ng-tns-c263290053-769&quot;&gt;
&lt;div class=&quot;container&quot;&gt;
&lt;div id=&quot;model-response-message-contentr_bfb50fc8f1f4512c&quot; class=&quot;markdown markdown-main-panel stronger enable-updated-hr-color&quot;&gt;
&lt;p&gt;Real innovation starts with a strong foundation, and at commercetools, that comes from the perfect balance of our product and our people.&lt;/p&gt;
&lt;p&gt;Behind every leap forward is a collective of builders, explorers, doers, makers, and problem-solvers.The kind of people who not only pioneered a more flexible approach to commerce architecture but also shaped the culture of experimentation that approach unlocked. Together they are the engine of commerce innovation today.&lt;/p&gt;
&lt;p&gt;At commercetools, we power the next era of autonomous commerce for our customers. Whether it’s AI-driven solutions that help enterprises make smarter business decisions, bridging digital and physical shopping experiences, or enabling entirely new ways for industries to connect with their customers, we help the world’s most ambitious companies experiment, scale, and grow without limits.&lt;/p&gt;
&lt;p&gt;Here the best idea wins, not the loudest voice. You will have the tools, trust, and space to not only build the future of commerce, but to build your own.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Your Impact&lt;/strong&gt;&lt;/h4&gt;
&lt;p data-path-to-node=&quot;3&quot;&gt;&lt;span data-path-to-node=&quot;3,1&quot;&gt;&lt;span class=&quot;citation-2853&quot;&gt;You own AI capabilities end-to-end:&amp;nbsp; from the data and context that feed a model, through agent orchestration, to the generative UI a user sees and trusts. You&#39;ve personally shipped and operated full-stack apps in production, so backend, frontend, data, and ML aren&#39;t four teams you coordinate with, they&#39;re four things you do. You&#39;re not a research scientist; you wield models and engineer ruthlessly around their uncertainty.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p data-path-to-node=&quot;4&quot;&gt;&lt;strong data-path-to-node=&quot;4&quot; data-index-in-node=&quot;0&quot;&gt;You will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Build agent loops and orchestration: tool use, structured outputs, business-rule enforcement, graceful failure&lt;/li&gt;
&lt;li&gt;Build the integration layer (via MCP) that lets agents securely call backend systems and business APIs&lt;/li&gt;
&lt;li&gt;Render model output into live, streamed, accessible UI via generative-UI protocols&lt;/li&gt;
&lt;li&gt;Ground models in real data: retrieval, embeddings, and feedback loops that actually close&lt;/li&gt;
&lt;li&gt;Treat evals as a first-class system - provable improvement, not vibes&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Take a capability from prompt-in-a-notebook to a measured, guard-railed production feature&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;6&quot;&gt;&lt;span data-path-to-node=&quot;6,1&quot;&gt;&lt;span class=&quot;citation-2837&quot;&gt;This is a full time hybrid role location in either&amp;nbsp; &lt;/span&gt;&lt;strong data-path-to-node=&quot;6,1&quot; data-index-in-node=&quot;57&quot;&gt;&lt;span class=&quot;citation-2837&quot;&gt;Berlin, Munich, London or Valencia&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;6,3&quot;&gt;.&lt;/span&gt;&lt;/p&gt;
&lt;p data-path-to-node=&quot;6&quot;&gt;&lt;strong&gt;&lt;span data-path-to-node=&quot;6,3&quot;&gt;What Sets Y&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-path-to-node=&quot;6,3&quot;&gt;ou Apart&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p data-path-to-node=&quot;8&quot;&gt;You&#39;re a creative problem-solver who is wired to find solutions. You confidently dive into complex challenges and have a talent for making them simple for others. Your curiosity drives you to constantly grow and contribute to an environment of trust and teamwork. Great ideas come from many paths, and your unique perspective matters more than checking every box. What matters most is the mindset you bring to the work.&lt;/p&gt;
&lt;p&gt;&lt;strong data-path-to-node=&quot;9&quot; data-index-in-node=&quot;0&quot;&gt;You bring:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Shipped full-stack apps to production and owned them end-to-end: frontend through backend to deploy and operate, not handed off at a layer boundary&lt;/li&gt;
&lt;li&gt;5+ years shipping production software, 2+ building with LLMs in production (real users, not demos)&lt;/li&gt;
&lt;li&gt;Hands-on experience with UI protocols (A2UI, AG-UI, MCP-UI, or similar). You&#39;ve built against a generative/agent-driven UI protocol, not just consumed a REST API&lt;/li&gt;
&lt;li&gt;The AI spine: prompt/context engineering, agents, tool use, structured outputs, evals, MCP Python and TypeScript/Node + React; comfortable with async, streaming, and observability&lt;/li&gt;
&lt;li&gt;Working fluency with retrieval/embeddings and SQL&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-path-to-node=&quot;13&quot;&gt;&lt;span data-path-to-node=&quot;13,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,0&quot; data-index-in-node=&quot;0&quot;&gt;&lt;span class=&quot;citation-2822&quot;&gt;Nice to Have:&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Fine-tuning/distillation, e-commerce or marketplace systems, and a track record in 0→1&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;h4&gt;&lt;strong&gt;Our Benefits&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;Because work and life are connected, our benefits are too. We’ve designed them to give you the security, flexibility, and opportunities you need to focus on what matters most.&lt;/p&gt;
&lt;p&gt;🩺 &lt;strong&gt;Comprehensive health benefits&lt;/strong&gt; for you and your dependents, including access to OpenUp for personalized mental health support&lt;/p&gt;
&lt;p&gt;📚 &lt;strong&gt;Learning and development &lt;/strong&gt;opportunities including an annual learning budget, access to self-paced learning platforms and language training, personalized coaching, mentorship, and leadership programs&lt;/p&gt;
&lt;p&gt;🍼 &lt;strong&gt;Family Leave Plus&lt;/strong&gt; gives you additional fully paid weeks of parental leave on top of government-provided leave, so you can spend more time with your new addition&lt;/p&gt;
&lt;p&gt;📈 &lt;strong&gt;Our equity participation program&lt;/strong&gt; allows you to share in our success&amp;nbsp;&lt;/p&gt;
&lt;p&gt;For more information on our benefits, &lt;a href=&quot;https://commercetools.com/careers/our-benefits&quot;&gt;visit this page.&lt;/a&gt;&lt;/p&gt;
&lt;h4&gt;&amp;nbsp;&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;Come as you are. Build with us.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Your unique perspective is essential to our success. We are committed to building a team that reflects the world around us because we know it’s the only way to build the future. We celebrate our differences and have created a hiring process that’s fair, inclusive, and designed to let your talent shine.&lt;/p&gt;
&lt;p&gt;We proudly welcome applicants of every race, color, religion, gender identity, sexual orientation, age, and any other part of your identity that makes you who you are. As an equal opportunity employer, we believe that our strength lies in our diversity, and we invite you to be a part of our global community.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;For more information on our diversity, equity, inclusion, and belonging practices, &lt;a href=&quot;https://commercetools.com/careers/dei-esg&quot;&gt;visit this page&lt;/a&gt;.&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;
&lt;/section&gt;
&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; color: rgb(0, 0, 0); font-size: 12pt;&quot;&gt;&lt;strong&gt;About Glean:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Glean is the Work AI platform that helps everyone work smarter with AI. What began as the industry’s most advanced enterprise search has evolved into a full-scale Work AI ecosystem, powering intelligent Search, an AI Assistant, and scalable AI agents on one secure, open platform. With over 100 enterprise SaaS connectors, flexible LLM choice, and robust APIs, Glean gives organizations the infrastructure to govern, scale, and customize AI across their entire business - without vendor lock-in or costly implementation cycles.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;At its core, Glean is redefining how enterprises find, use, and act on knowledge. Its Enterprise Graph and Personal Knowledge Graph map the relationships between people, content, and activity, delivering deeply personalized, context-aware responses for every employee. This foundation powers Glean’s agentic capabilities - AI agents that automate real work across teams by accessing the industry’s broadest range of data: enterprise and world, structured and unstructured, historical and real-time. The result: measurable business impact through faster onboarding, hours of productivity gained each week, and smarter, safer decisions at every level.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Recognized by Fast Company as one of the World’s Most Innovative Companies (Top 10, 2025), by CNBC’s Disruptor 50, Bloomberg’s AI Startups to Watch (2026), Forbes AI 50, and Gartner’s Tech Innovators in Agentic AI, Glean continues to accelerate its global impact. With customers across 50+ industries and 1,000+ employees in more than 25 countries, we’re helping the world’s largest organizations make every employee AI-fluent, and turning the superintelligent enterprise from concept into reality.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;If you’re excited to shape how the world works, you’ll help build systems used daily across Microsoft Teams, Zoom, ServiceNow, Zendesk, GitHub, and many more - deeply embedded where people get things done. You’ll ship agentic capabilities on an open, extensible stack, with the craft and care required for enterprise trust, as we bring Work AI to every employee, in every company.&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;About the Role:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Glean is building a world-class data organization spanning data science, applied science, data engineering, and business analytics. This role sits within the Growth and Enterprise Readiness Data Science team, with a primary focus on accelerating user adoption, engagement, and sustained product usage.&amp;nbsp;As a Growth Data Scientist, you will be the quantitative partner to Growth Product, Engineering, and Applied AI (Post Sales). You’ll turn ambiguous growth opportunities into measurable product bets, build the measurement and experimentation systems that allow us to learn quickly, and use behavioral data to identify where Glean can create substantially more value for its users.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;You will:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Define and evolve Glean’s growth measurement framework across acquisition, activation, engagement, retention, resurrection, and expansion, including metrics such as WAU, activation, engagement intensity, retention, and feature adoption&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Build and analyze end-to-end user and account growth funnels to understand where users experience value, where they drop off, and which behaviors are most predictive of durable engagement&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Diagnose adoption gaps and develop bottoms-up growth strategies for high-impact enterprise accounts, identifying where product, deployment, engagement, or organizational barriers are limiting growth and partnering with Applied AI and R&amp;amp;D leaders on targeted interventions.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Identify and size high-leverage growth opportunities across onboarding, product discoverability, education, lifecycle messaging, collaboration and virality, and new product surfaces&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Partner across R&amp;amp;D and Applied AI to turn product capabilities and behavioral insights into scalable adoption plays, identifying the customers and user populations best suited for new experiences and translating those opportunities into targeted field interventions.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Partner closely with Product, Design, and Engineering to translate product ideas into testable hypotheses, well-defined success metrics, instrumentation plans, and decision criteria&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Design and analyze rigorous A/B tests, phased rollouts, and quasi-experiments; use causal evidence to recommend whether products should launch, iterate, or change direction&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Develop behavioral and needs-based user segments and translate those insights into targeted product interventions&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Inform roadmap and investment decisions by quantifying reachable populations, expected impact, confidence, dependencies, and tradeoffs before significant development begins&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Build trusted, reusable growth datasets, dashboards, and self-serve analytical tools that allow Product and Engineering partners to independently understand product health and investigate changes&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Lead cross-functional data science projects end-to-end, translating ambiguous product questions into clear insights, recommendations, and decisions for audiences ranging from engineers to executives&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Example areas of focus could include improving new-user onboarding and activation, converting occasional users into habitual users, increasing adoption of emerging AI experiences, optimizing high-traffic entry surfaces, improving feature discovery, developing lifecycle strategies, and building account-level adoption frameworks for enterprise customers, and translating new product capabilities into scalable Applied AI adoption motions.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;You are:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;7+ years of experience in a highly quantitative data science, product analytics, or growth analytics role, with a degree in Statistics, Mathematics, Computer Science, or a related field&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Demonstrated experience partnering with Product and Engineering teams to identify opportunities and influence product roadmap decisions&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Strong grounding in statistics, experimentation, causal inference, statistical power, segmentation, funnel analysis, and retention analysis&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Exceptionally high AI proficiency through habitual, high-value use of LLMs, with sound judgment about when and how to apply them, rigorous validation, and continuous workflow improvement&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Experience designing and analyzing product experiments and communicating causal findings in a way that drives clear product decisions&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Strong proficiency in SQL and practical fluency in a statistical programming language such as Python or R&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Experience building durable analytical datasets, metrics, dashboards, and data models rather than relying primarily on ad hoc analysis. dbt experience is a plus.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;A strong product and business mindset, with experience defining KPIs, guardrail metrics, and measurement frameworks that influence decisions&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Ability to independently own complex projects end-to-end, from problem framing and measurement through analysis, recommendation, and follow-through&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Clear, concise communication skills, with the ability to explain complex quantitative findings to both technical and non-technical audiences&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;You are a particularly good fit if:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You have experience in B2B SaaS, especially enterprise AI, or have worked on products where adoption occurs across both users and accounts&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You have experience partnering with GTM or Post-Sales teams and are comfortable using data to challenge assumptions, shape account strategy, and drive impact through action.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You have a track record of identifying growth opportunities from behavioral data and turning them into shipped, measurable product interventions&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You have helped build experimentation or product-measurement capabilities that increased the velocity and quality of decision-making for an organization&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You combine strong quantitative rigor with product intuition and are comfortable making recommendations in highly ambiguous problem spaces&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You have a very strong sense of ownership and self-motivation. You are laser-focused on delivering business impact while growing as an individual along with Glean&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;You are good at managing evolving priorities while successfully delivering core initiatives&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Location:&lt;/strong&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;This role is hybrid (4 days a week in our Mountain View office)&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Compensation &amp;amp; Benefits:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;The standard base salary range for this position is $200,000 - $260,000 annually. Compensation offered will be determined by factors such as location, level, job-related knowledge, skills, and experience. Certain roles may be eligible for variable compensation, equity, and benefits.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;We offer a comprehensive benefits package including competitive compensation, Medical, Vision, and Dental coverage, generous time-off policy, and the opportunity to contribute to your 401k plan to support your long-term goals. When you join, you&#39;ll receive a home office improvement stipend, as well as an annual education and wellness stipends to support your growth and wellbeing. We foster a vibrant company culture through regular events, and provide healthy lunches daily to keep you fueled and focused.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;We’re committed to building and sustaining a diverse, inclusive workplace. We strive to attract and retain people with a wide range of backgrounds, experiences, and perspectives, and we do not discriminate on the basis of gender, ethnicity, sexual orientation, religion, civil or family status, age, disability, or race.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;#LI-HYBRID&lt;/span&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;AI-First Mindset at Glean:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;At Glean, AI fluency is core to how we work and we&#39;re committed to ensuring every new hire feels confident integrating AI into their everyday work. &lt;strong&gt;As part of the interview process, you&#39;ll complete a brief AI-focused exercise or discussion so we can understand how you think about, design, and use AI to drive impact in your role. &lt;/strong&gt;Feel free to reference any tools, platforms, or workflows you use today — prior Glean experience isn&#39;t required.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Global Data Privacy Notice for Job Candidates and Applicants:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Depending on your location, the General Data Protection Regulation (GDPR), California Consumer Privacy Act (CCPA), or other privacy laws may regulate the way we manage the data of job applicants. Our full notice outlining how data will be processed as part of the application procedure for applicable locations is available in our &lt;a href=&quot;https://www.glean.com/privacy&quot;&gt;&lt;strong&gt;Privacy Policy&lt;/strong&gt;&lt;/a&gt;. By submitting your application, you are agreeing to our use and processing of your data as required. US applicants and their applications are subject to arbitration of disputes as outlined in our &lt;a href=&quot;https://www.glean.com/arbitrationagreement&quot;&gt;&lt;strong&gt;Applicant Arbitration Agreement&lt;/strong&gt;&lt;/a&gt;.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;br&gt;By clicking “Submit Application,” I confirm that I have read the Global Data Privacy Notice and the &lt;a href=&quot;https://www.glean.com/arbitrationagreement&quot;&gt;&lt;strong&gt;Applicant Arbitration Agreement&lt;/strong&gt;&lt;/a&gt;, and I agree to the terms.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h4&gt;The role&lt;/h4&gt;
&lt;p&gt;&lt;a href=&quot;https://woocommerce.com/&quot;&gt;We’re&lt;/a&gt; hiring a senior, hands-on Product Manager to join WooCommerce Payments and take ownership of a defined area within our payments products and partner integrations.&lt;/p&gt;
&lt;p&gt;You’ll collaborate closely with the Head of Product, and work day-to-day with engineering, design, support, and partnerships. This role is deeply executional. You’ll spend much of your time in the work: in Linear writing and refining issues, triaging bugs and incidents, reviewing and shaping flows in Figma, creating lightweight prototypes, and writing briefs or PRDs when they’re needed.&lt;/p&gt;
&lt;p&gt;Payments at WooCommerce run at a serious scale—billions in total payment volume—and the quality of this experience directly affects merchant revenue, shopper conversion, and the success of Woo’s commercial engine. This role sits right where reliability, trust, and execution matter most.&lt;/p&gt;
&lt;h4&gt;What you’ll work on&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Own product direction and execution for a key part of the payments product area, with clear goals, priorities, and measurable outcomes.&lt;/li&gt;
&lt;li&gt;Improve merchant and shopper experiences across onboarding, checkout, refunds and disputes, payouts, reporting, and overall reliability.&lt;/li&gt;
&lt;li&gt;Raise the quality bar by reducing failures and friction, lowering support volume, and improving product ratings and merchant trust.&lt;/li&gt;
&lt;li&gt;Use data, support signals, and merchant feedback to decide what to work on next, define success measures, and make tradeoffs explicit.&lt;/li&gt;
&lt;li&gt;Work closely with priority payments partners (including Stripe and PayPal) to improve integrations, ship changes, manage dependencies, and resolve issues.&lt;/li&gt;
&lt;li&gt;Keep stakeholders aligned through clear, direct writing and communication about progress, risks, and decisions.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;What we’re looking for&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;7+ years in product roles, with senior IC experience owning complex problem spaces and influencing cross-functional teams through clarity of communication and precision of execution.&lt;/li&gt;
&lt;li&gt;4+ years in payments or fintech, ideally on products operating at scale; experience with large or global launches is a plus.&lt;/li&gt;
&lt;li&gt;Strong product judgment. You can make good calls in messy situations and don’t need perfect information to move forward.&lt;/li&gt;
&lt;li&gt;Comfort working on critical, high-trust systems where reliability matters and small changes can have outsized impact.&lt;/li&gt;
&lt;li&gt;Ability to work deeply with engineers and designers on complex problems, including technical constraints and tradeoffs.&lt;/li&gt;
&lt;li&gt;Strong analytical habits and a practical approach to metrics, dashboards, and instrumentation.&lt;/li&gt;
&lt;li&gt;Clear written and verbal communication in a distributed, async environment.&lt;/li&gt;
&lt;li&gt;Familiarity with WooCommerce, &lt;a href=&quot;https://wordpress.org/&quot;&gt;WordPress&lt;/a&gt;, or open-source ecosystems is a plus.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Salary range: $170,000-$240,000 USD.&lt;/strong&gt;&amp;nbsp; Please note that salary ranges are global, regardless of location, and we pay in local currency.&lt;/p&gt;
&lt;p&gt;We are searching for high-caliber candidates with the skills and qualities to have a net positive for Automattic. Pay will reflect the potential contribution and the impact you can bring, which may, in some cases, go beyond the range stated.&lt;/p&gt;
&lt;p&gt;We’re pleased to offer a straightforward, competitive base salary, providing financial clarity without complex variable components. This isn’t your typical work-from-home job: we are a fully-remote company with an open vacation policy. To see a full list of benefits by country, consult our &lt;a href=&quot;https://automattic.com/benefits/&quot;&gt;Benefits Page&lt;/a&gt;. And check out these links to learn more about &lt;a href=&quot;https://automattic.com/how-we-hire/&quot;&gt;How We Hire&lt;/a&gt; and &lt;a href=&quot;https://automattic.com/expectations/&quot;&gt;What We Expect from Ourselves&lt;/a&gt;.&amp;nbsp;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;#LI-Remote&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h4&gt;About Automattic&amp;nbsp;&lt;/h4&gt;
&lt;p&gt;Now in &lt;a href=&quot;https://timeline.automattic.com/&quot;&gt;our 20th year&lt;/a&gt;, we’re the people behind &lt;a href=&quot;http://wordpress.com/&quot;&gt;WordPress.com&lt;/a&gt;, &lt;a href=&quot;https://href.li/?http://woocommerce.com/&quot;&gt;WooCommerce&lt;/a&gt;, &lt;a href=&quot;https://www.beeper.com/&quot;&gt;Beeper&lt;/a&gt;, &lt;a href=&quot;https://href.li/?https://www.tumblr.com/&quot;&gt;Tumblr&lt;/a&gt;, &lt;a href=&quot;https://href.li/?http://simplenote.com/&quot;&gt;Simplenote&lt;/a&gt;, &lt;a href=&quot;https://href.li/?http://jetpack.com/&quot;&gt;Jetpack&lt;/a&gt;, &lt;a href=&quot;https://href.li/?http://longreads.com/&quot;&gt;Longreads&lt;/a&gt;, &lt;a href=&quot;https://href.li/?https://dayoneapp.com/&quot;&gt;Day One&lt;/a&gt;, &lt;a href=&quot;https://href.li/?https://www.pocketcasts.com/&quot;&gt;PocketCasts&lt;/a&gt;, and more. We believe in making the web a better place.&lt;/p&gt;
&lt;p&gt;We’re a distributed company with more than 1500 Automatticians in nearly every corner of the globe, speaking over a hundred different languages. Enriched by this diversity, we’re united by a singular mission: to democratize publishing, commerce, and messaging so anyone with a story can tell it, anyone with a product can sell it, and everyone can manage their communications from a single source. In short, we help maintain a balance in society, creating and continually refining powerful tools people can use to compete fairly—regardless of income, gender, politics, language, or where they live in the world.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/Automattic&quot;&gt;We believe in Open Source&lt;/a&gt;, and the vast majority of our work is available under the &lt;a href=&quot;https://en.wikipedia.org/wiki/GNU_General_Public_License&quot;&gt;GPL&lt;/a&gt;. Automattic is a &lt;a href=&quot;https://mostlovedworkplace.com/companies/automattic-inc/&quot;&gt;Most Loved Company&lt;/a&gt;, an Equal Opportunity employer, and &lt;a href=&quot;https://disabilityconfident.campaign.gov.uk/&quot;&gt;Disability Confident Committed&lt;/a&gt;. (&lt;a href=&quot;https://happinessengineer.blog/2022/09/08/happiness-for-everyone-working-with-a-disability-at-automattic/&quot;&gt;Here’s what that might mean for you&lt;/a&gt;.) If you need accommodations during the application or interview process, please&amp;nbsp;&lt;a href=&quot;https://automattic.com/application-accommodation-request/&quot;&gt;fill out this form&lt;/a&gt;. We are committed to ensuring an accessible hiring process for all candidates. Learn more about our &lt;a href=&quot;https://automattic.com/automattician-resource-groups/&quot;&gt;Employee Resource Groups&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;You can track your application status and more at &lt;a href=&quot;https://my.greenhouse.io/users/sign_in&quot; target=&quot;_blank&quot;&gt;MyGreenhouse&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;To learn about how we handle your data, please review our&amp;nbsp;&lt;a class=&quot;underline underline underline-offset-2 decoration-1 decoration-current/40 hover:decoration-current focus:decoration-current&quot; href=&quot;https://automattic.com/automattic-job-applicant-candidate-privacy-notice/&quot;&gt;Job Applicant &amp;amp; Candidate Privacy Notice&lt;/a&gt; and our &lt;a class=&quot;underline underline underline-offset-2 decoration-1 decoration-current/40 hover:decoration-current focus:decoration-current&quot; href=&quot;https://automattic.com/privacy/&quot;&gt;Privacy Policy&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, sexual orientation, gender identity, national origin, disability, or status as a protected veteran. View the “Know Your Rights: Workplace Discrimination is Illegal” poster&lt;/em&gt; &lt;a href=&quot;https://automattic.wordpress.com/wp-content/uploads/2026/03/22-088_eeoc_knowyourrights6.12.pdf&quot;&gt;&lt;em&gt;here&lt;/em&gt;&lt;/a&gt;&lt;em&gt;. Automattic participates in the&lt;/em&gt; &lt;a href=&quot;https://automattic.wordpress.com/wp-content/uploads/2026/03/e-verify_participation_poster_eng_es.pdf&quot;&gt;&lt;em&gt;E-Verify program&lt;/em&gt;&lt;/a&gt;&lt;em&gt; in certain locations, as required by law&lt;/em&gt;.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;ace-line gutter-author-p-118095 emptyGutter&quot;&gt;
&lt;h2&gt;Who we are&lt;/h2&gt;
&lt;h3&gt;About Stripe&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Stripe is a financial infrastructure platform for businesses. Millions of companies—from the world’s largest enterprises to the most ambitious startups—use Stripe to accept payments, grow their revenue, and accelerate new business opportunities. Our mission is to increase the GDP of the internet, and we have a staggering amount of work ahead. That means you have an unprecedented opportunity to put the global economy within everyone’s reach while doing the most important work of your career.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;About the team&lt;/h3&gt;
&lt;p&gt;Data Science at Stripe is a vibrant community where data analysts and data scientists learn and grow together. You&#39;ll work with some of the most fundamental data at Stripe, and use that data to help drive company-wide initiatives. We have a variety of Data Analytics roles and teams across Stripe and Data Analysts are hired in line with the business needs and domain of the organization they will support.&lt;/p&gt;
&lt;h2&gt;What you’ll do&lt;/h2&gt;
&lt;p&gt;We’re looking for a Data Analyst to partner with Stripe’s Global organization, helping millions of users sell around the world. You’ll help build analytics and data products for solutions such as Adaptive Pricing and Stripe Managed Payments, as well as Stripe’s expansion into new markets across LATAM and EMEA.&lt;/p&gt;
&lt;h3&gt;Responsibilities&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Design and build scalable data models and infrastructure to power product analytics and metrics reporting as we launch and grow new products&lt;/li&gt;
&lt;li&gt;Own business-critical data products, including Tier-1 datasets and production pipelines, ensuring reliability through rigorous testing, monitoring, and documentation&lt;/li&gt;
&lt;li&gt;Build and maintain the metric definitions, metadata, and business context that enable AI agents to help stakeholders explore trusted data and answer business questions independently&lt;/li&gt;
&lt;li&gt;Develop dashboards, automated reporting, and thoughtful analyses to surface actionable insights and proactively identify business opportunities&lt;/li&gt;
&lt;li&gt;Partner closely with senior business leaders to translate business needs into analytical questions and deliver clear recommendations through deep-dive analyses&lt;/li&gt;
&lt;li&gt;Shape product and business strategy across global markets by distilling complex findings into compelling data narratives for senior stakeholders&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Who you are&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re looking for someone who meets the minimum requirements to be considered for the role. If you meet these requirements, you are encouraged to apply. The preferred qualifications are a bonus, not a requirement.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Minimum requirements&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;6+ years of full-time experience in Data Engineering, Analytics Engineering, Business Intelligence Engineering, or a related analytical role&lt;/li&gt;
&lt;li&gt;Proficiency in SQL, including complex query optimization and data modeling&lt;/li&gt;
&lt;li&gt;Proficiency in Scala or Python for data pipeline development, not just scripting and SQL&lt;/li&gt;
&lt;li&gt;Experience with distributed data frameworks like Spark to write and debug data pipelines&lt;/li&gt;
&lt;li&gt;Experience with workflow orchestration tools (e.g. Airflow, Flyte, or equivalent)&lt;/li&gt;
&lt;li&gt;Proven ability to design, implement, and maintain production-grade data pipelines and dashboards&lt;/li&gt;
&lt;li&gt;Good understanding of development processes and best practices like engineering standards, code reviews, and testing&lt;/li&gt;
&lt;li&gt;Ability to clearly communicate results and drive impact with cross-functional partners&lt;/li&gt;
&lt;li&gt;Experience owning production data products with defined quality standards, testing, and documentation&lt;/li&gt;
&lt;li&gt;Proficiency with AI tools to accelerate model development, analysis, and coding&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;

&lt;p&gt;Scale&#39;s Data Analytics team is centralized, embedding data analysts across delivery, operations, finance, and engineering to turn ambiguous problems into clear, actionable insights. As a Senior Data Analyst for Public Sector, you&#39;ll build analytics solutions from the ground up - partnering closely with cross-functional teams and leadership to solve complex problems, design dashboards, build tables, and perform ad-hoc analyses that shape how Scale runs and measures its Public Sector business.&lt;br&gt;&lt;br&gt;We&#39;re looking for someone who&#39;s relentlessly curious, comfortable owning ambiguity, and skilled at turning cross-functional relationships into sustainable, scalable analytics solutions.&lt;br&gt;&lt;br&gt;&lt;strong&gt;&lt;em&gt;Active Secret U.S. security clearance required&lt;br&gt;&lt;br&gt;&lt;/em&gt;&lt;/strong&gt;&lt;strong&gt;You will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own data quality for your domain - document models, troubleshoot discrepancies, and establish centralized metric definitions&lt;/li&gt;
&lt;li&gt;Collaborate with cross-functional teams to identify, define, and track key metrics to be used in monitoring, planning, and one-off decision-making&lt;/li&gt;
&lt;li&gt;Develop repeatable, scalable analytical solutions, such as dashboards, data models, or standard processes&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Partner with Ops to identify and track efficiency initiatives, measuring their impact on cost, quality, and delivery outcomes over time&lt;/li&gt;
&lt;li&gt;Partner with Finance to analyze cost drivers across programs and help inform pricing strategy&lt;/li&gt;
&lt;li&gt;Be willing to deepdive when needed and dig into the messy details to get to the root of a problem&lt;/li&gt;
&lt;li&gt;Initiate and drive complex projects to completion with minimal guidance&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Ideally you&#39;d have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;6+ years of relevant work experience&lt;/li&gt;
&lt;li&gt;Advanced SQL skills and experience building with data modeling tools (e.g. DBT)&lt;/li&gt;
&lt;li&gt;Experience building dashboards and reports with BI tools (e.g. Tableau, Metabase)&lt;/li&gt;
&lt;li&gt;Strong business acumen - comfortable partnering directly with cross-functional stakeholders&lt;/li&gt;
&lt;li&gt;Excellent communication skills - able to translate technical analysis into clear, actionable narratives&lt;/li&gt;
&lt;li&gt;Comfort with ambiguity in a fast-moving environment and able to make sound trade-offs&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Active Secret U.S. security clearance is required; Top Secret U.S. clearance is preferred&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Nice to haves:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Familiarity working within air-gapped/federal environments and navigating their constraints&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Prior experience supporting a Business Operations function, with exposure to process analytics or process mining (e.g. workflow optimization)&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;em&gt;Compensation packages at Scale for eligible roles include base salary, equity, and benefits. The range displayed on each job posting reflects the minimum and maximum target for new hire salaries for the position and may be inclusive of several career levels at Scale; it will be determined during the interview process based on work location and additional factors, including job-related skills, experience, qualifications, interview performance, and relevant education or training. Scale employees in eligible roles are also granted equity based compensation, subject to Board of Director approval. Your recruiter can share more about the specific salary range for your preferred location during the hiring process, and confirm whether the hired role will be eligible for equity grant. You&#39;ll also receive benefits including, but not limited to: comprehensive health, dental and vision coverage, retirement benefits, a learning and development stipend, and generous PTO. Additionally, this role may be eligible for additional benefits such as a commuter stipend.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;The base salary range for this full-time position in the location of Washington DC is:&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$184,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$230,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;em&gt;PLEASE NOTE:&amp;nbsp;&lt;/em&gt;&lt;/strong&gt;&lt;em&gt;Our policy requires a 90-day waiting period before reconsidering candidates for the same role. This allows us to ensure a fair and thorough evaluation of all applicants.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Us:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;At Scale, our mission is to develop reliable AI systems for the world&#39;s most important decisions. Our products provide the high-quality data and full-stack technologies that power the world&#39;s leading models, and help enterprises and governments build, deploy, and oversee AI applications that deliver real impact. We work closely with industry leaders like Meta, &lt;/em&gt;&lt;em&gt;Ernst&lt;/em&gt;&lt;em&gt; &lt;/em&gt;&lt;em&gt;&amp;amp;&lt;/em&gt;&lt;em&gt; Young, Mayo Clinic, Time Inc., the Government of Qatar, and U.S. government agencies including the Army and Air Force. We are expanding our team to accelerate the development of AI applications.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We believe that everyone should be able to bring their whole selves to work, which is why we are proud to be an inclusive and equal opportunity workplace. We are committed to equal employment opportunity regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability status, gender identity or Veteran status.&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are committed to working with and providing reasonable accommodations to applicants with physical and mental disabilities. If you need assistance and/or a reasonable accommodation in the application or recruiting process due to a disability, please contact us at accommodations@scale.com. Please see the United States Department of Labor&#39;s &lt;/em&gt;&lt;a href=&quot;https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12ScreenRdr.pdf&quot;&gt;&lt;em&gt;Know Your Rights poster&lt;/em&gt;&lt;/a&gt;&lt;em&gt; for additional information.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We comply with the United States Department of Labor&#39;s &lt;/em&gt;&lt;em&gt;Pay Transparency provision&lt;/em&gt;&lt;em&gt;.&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;strong&gt;PLEASE NOTE: &lt;/strong&gt;We collect, retain and use personal data for our professional business purposes, including notifying you of job opportunities that may be of interest and sharing with our affiliates. We limit the personal data we collect to that which we believe is appropriate and necessary to manage applicants’ needs, provide our services, and comply with applicable laws. Any information we collect in connection with your application will be treated in accordance with our internal policies and programs designed to protect personal data. Please see our &lt;a href=&quot;https://scale.com/legal/privacy&quot; target=&quot;_blank&quot;&gt;privacy policy&lt;/a&gt; for additional information.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;h3&gt;&lt;strong&gt;Change the way the world travels&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Join the GetYourGuide journey to connect people with unforgettable travel experiences around the world. Millions look to us for unique activities they can trust, and it’s all powered by our commitment to make every single journey extraordinary - including yours.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Ready to unlock your potential with a community of fellow explorers? Find your next role at our Berlin HQ or one of our local offices around the globe, from New York to Bangkok. Head to&amp;nbsp;&lt;a href=&quot;https://www.getyourguide.careers/&quot;&gt;getyourguide.careers&lt;/a&gt; to take the first step.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Your mission&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;GetYourGuide&#39;s On-Trip product group owns the entire post-booking experience: from the moment a traveler completes checkout through fulfillment, supplier coordination, to agentic care resolution. As GPM, you will lead a group of product managers, set strategy, coach a high-performing team, and drive measurable outcomes on some of the highest-leverage surfaces in the business. What you&#39;ll own:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;On-Trip Domain:&lt;/strong&gt; Fulfillment (contextual UX, self-service, modification and cancellation), AI Resolution (unified care and chat automation, currently resolving a significant share of contacts already with AI), and Supplier-Traveler Coordination (off-platform observability, supplier messaging, and coordination tooling).&lt;/li&gt;
&lt;li&gt;Manage three PMs in Zurich. You report to the Director of Product, Traveler, who is based in Berlin.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Your toolkit&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Demonstrated ability to synthesise a complex, multi-pillar strategy into a clear and opinionated thesis for executive audiences with a coherent point of view beyond executional updates.&lt;/li&gt;
&lt;li&gt;Experience managing and coaching junior/senior/lead PMs who own their own domains, with evidence that their output improved under your management.&lt;/li&gt;
&lt;li&gt;Strong commercial instinct: able to size problems with rough numbers, make ROI cases, and commit to metrics.&lt;/li&gt;
&lt;li&gt;Track record operating in an operationally complex domain — marketplace, payments, post-purchase, or customer service technology.&lt;/li&gt;
&lt;li&gt;Comfortable with occasional travel to Berlin for stakeholders and leadership engagement.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Extras that give you an edge&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&amp;nbsp;Familiarity with AI-assisted customer resolution, supplier-facing product, or payment corridors in a global marketplace.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;How we’ll make your career journey extraordinary&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Annual personal growth budget and mentorship programs for continuous learning and development&lt;/li&gt;
&lt;li&gt;Work from anywhere in the world for 30 days per year&lt;/li&gt;
&lt;li&gt;A hybrid working approach with three days of in office collaboration (Mon, Tue, Thur) and two days of optional at home focus time.&lt;/li&gt;
&lt;li&gt;Opportunities to collaborate and socialize with team members through quarterly team events and yearly company-wide events&lt;/li&gt;
&lt;li&gt;Monthly transportation and fitness budget&lt;/li&gt;
&lt;li&gt;Discounts for you, your friends, and family on GetYourGuide activities&lt;/li&gt;
&lt;li&gt;Language reimbursement program&lt;/li&gt;
&lt;li&gt;Health and wellness benefits&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;And more…&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;How to apply&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Submit your CV/resume in English using the form below. For tips and insights into our hiring process and culture, check out ‘&lt;a href=&quot;https://www.getyourguide.careers/how-we-hire&quot;&gt;how we hire&lt;/a&gt;’ and ‘&lt;a href=&quot;https://www.getyourguide.careers/life-at-getyourguide&quot;&gt;life at GetYourGuide&lt;/a&gt;’. If you have any further questions, please don’t hesitate to get in touch at &lt;a href=&quot;mailto:jobs@getyourguide.com&quot;&gt;jobs@getyourguide.com&lt;/a&gt;.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;We’re an equal opportunities employer&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Our commitment is that every qualified person will be evaluated according to their skills regardless of age, gender identity, ethnicity, sexual orientation, disability status, or religion. Please refrain from including your picture and age with your application.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;

&lt;p&gt;At Lyft, our purpose is to serve and connect. We aim to achieve this by cultivating a work environment where all team members belong and have the opportunity to thrive.&lt;/p&gt;
&lt;p&gt;As a Data Scientist on the Mapping team, you will collaborate with our world class team of scientists, engineers, product managers, and designers to grow and improve the quality of recommended routes and accuracy of our travel time estimations. We&#39;re looking for a passionate, driven Data Scientist who is excited to dive into our geospatial, behavioural and mobility data, and build a best-in-class mapping product that provides safe, efficient, and seamless navigation for our rideshare drivers.&lt;/p&gt;
&lt;p&gt;Data Science is at the heart of Lyft’s products and decision-making. You will leverage data and rigorous, analytical thinking to shape our mapping products and make business decisions that put our customers first. The Mapping team serves models and systems that determine the most efficient routes, fastest travel estimates and process real-time map data signals to detect traffic, closures and slowdowns.&amp;nbsp; Working with our business and analytics partners, the team owns tools to ensure Lyft offers routes that our users trust. This will involve identifying and scoping opportunities, recommending technical solutions, designing experiments, and measuring the impact of new features. You will help us solve some of the most impactful problems in Mapping, including:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;How do we accurately predict acute and chronic traffic conditions?&lt;/li&gt;
&lt;li&gt;How do we improve the recommendations of our routing algorithms?&lt;/li&gt;
&lt;li&gt;How do we keep our travel estimation promises to our riders and drivers?&lt;/li&gt;
&lt;li&gt;How do we benchmark and measure the success of our services?&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Responsibilities:&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Own the complete lifecycle of algorithmic solutions from problem formulation, data exploration, and feature engineering to deployment, monitoring, and iteration&lt;/li&gt;
&lt;li&gt;Prioritize and lead deep dives into our data to uncover new product and business opportunities&lt;/li&gt;
&lt;li&gt;Partner closely with Engineering to build and scale production-grade ML systems, real-time inference services, batch pipelines, and feature stores&lt;/li&gt;
&lt;li&gt;Design, implement, and analyze different types of experiments, and facilitate and foster data-driven and informed decision making and prioritization&lt;/li&gt;
&lt;li&gt;Drive scientific excellence by introducing modern techniques in ML, optimization, reinforcement learning, or graph-based methods to unlock new product capabilities&lt;/li&gt;
&lt;li&gt;Establish metrics that measure the health of our products, as well as rider and driver experience&lt;/li&gt;
&lt;li&gt;Translate complex business challenges into concrete algorithmic solutions in close collaboration with Product, Engineering, Operations, and Science teams&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Experience:&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Advanced degree in a quantitative field such as statistics, physics, economics, operations research, neuroscience, or engineering, or relevant work experience&lt;/li&gt;
&lt;li&gt;3+ years hands-on experience in a data science or machine learning role working with production machine learning models and optimization systems&lt;/li&gt;
&lt;li&gt;Passion for solving unstructured and non-standard mathematical problems&lt;/li&gt;
&lt;li&gt;Experience independently driving multi-project algorithmic scopes and navigating technical ambiguity from ideation to delivery&lt;/li&gt;
&lt;li&gt;Experience with machine learning models in production, making practical tradeoffs among algorithm sophistication, compute complexity, maintainability, and extensibility in production environments&lt;/li&gt;
&lt;li&gt;Strong oral and written communication skills, and ability to collaborate with and influence cross-functional partners&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Working knowledge of modern machine learning frameworks and distributed computing systems, including PyTorch, TensorFlow, Ray, Spark, etc.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Benefits:&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Extended health and dental coverage options, along with life insurance and disability benefits&lt;/li&gt;
&lt;li&gt;Mental health benefits&lt;/li&gt;
&lt;li&gt;Family building benefits&lt;/li&gt;
&lt;li&gt;Child care and pet benefits&lt;/li&gt;
&lt;li&gt;Access to a Lyft funded Health Care Savings Account&lt;/li&gt;
&lt;li&gt;RRSP plan with company match to help save for your future&lt;/li&gt;
&lt;li&gt;In addition to provincial observed holidays, salaried team members are covered under Lyft&#39;s flexible paid time off policy. The policy allows team members to take off as much time as they need (with manager approval). Hourly team members get 15 days paid time off, with an additional day for each year of service&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Lyft is proud to support new parents with 18 weeks of paid time off, designed as a top-up plan to complement provincial programs. Biological, adoptive, and foster parents are all eligible.&lt;/li&gt;
&lt;li&gt;Subsidized commuter benefits and Lyft ride credits&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Lyft is committed to creating an inclusive workforce that fosters belonging. Lyft believes that every person has a right to equal employment opportunities without discrimination because of race, ancestry, place of origin, colour, ethnic origin, citizenship, creed, sex, sexual orientation, gender identity, gender expression, age, marital status, family status, disability, pardoned record of offences, or any other basis protected by applicable law or by Company policy. Lyft also strives for a healthy and safe workplace and strictly prohibits harassment of any kind.&amp;nbsp; Accommodation for persons with disabilities will be provided upon request in accordance with applicable law during the application and hiring process. Please contact your recruiter if you wish to make such a request.&lt;/p&gt;
&lt;p&gt;Lyft highly values having employees working in-office to foster a collaborative work environment and company culture. This role will be in-office on a hybrid schedule — Team Members will be expected to work in the office at least 3 days per week, including on Mondays, Wednesdays, and Thursdays. Lyft considers working in the office at least 3 days per week to be an essential function of this hybrid role. Your recruiter can share more information about the various in-office perks Lyft offers. Additionally, hybrid roles have the flexibility to work from anywhere for up to 4 weeks per year. #Hybrid&lt;/p&gt;
&lt;p&gt;The expected base pay range for this position in the Toronto area is CAD $108,000 - CAD $135,000, not inclusive of potential equity offering, bonus or benefits. Salary ranges are dependent on a variety of factors, including qualifications, experience and geographic location. Your recruiter can share more information about the salary range specific to your working location and other factors during the hiring process.&lt;/p&gt;
&lt;p&gt;Lyft may use artificial intelligence to screen applicants, however, Lyft employees make the ultimate selection and hiring decisions.&lt;/p&gt;
&lt;p&gt;This job fills an existing vacancy.&lt;/p&gt;

&lt;p&gt;Canonical is a leading provider of open source software and operating systems to the global enterprise and technology markets. Our platform, Ubuntu, is very widely used in breakthrough enterprise initiatives such as public cloud, data science, AI, engineering innovation and IoT. Our customers include the world&#39;s leading public cloud and silicon providers, and industry leaders in many sectors. The company is a pioneer of global distributed collaboration, with 1200+ colleagues in 75+ countries and very few office based roles. Teams meet two to four times yearly in person, in interesting locations around the world, to align on strategy and execution.&lt;/p&gt;
&lt;p&gt;The company is founder led, profitable and growing.&lt;/p&gt;
&lt;p&gt;Canonical’s product management team are technologists who have a passion for delivering products and solutions that help shape market demands while elevating open source software everywhere. This is a general application track for the product management positions at Canonical, across all levels of team leads. As a manager, you will lead a team of product managers, mentoring them to ensure their success while driving alignment with company goals. You will set a clear vision, prioritize work effectively, and ensure the team delivers high-quality products that meet business and user needs. Apply here if you excel at leadership, communication, and technical vision, and believe you can drive product strategy for the business needs of tomorrow. During the interview process we will identify specific software products which would be a good fit for your interests.&lt;/p&gt;
&lt;p&gt;We believe that open source is transforming the way that enterprises solve their business needs. Although open source has been around for thirty years, it is only now fundamental to every corner of the software landscape. Going forward we believe open source will have an even bigger impact as it moves into specialised vertical markets. Our goal is to make open source easier, more reliable and more secure for deployment and development. We strive to be the provider of ‘most software to most companies’, starting with Ubuntu but expanding to cover every class of application on every class of compute. To deliver on that ambition, we select product managers for their intellect and strong drive to advance the open source community. Together, we aim to improve open source quality, outreach, and impact. Our product managers set the vision and the direction to ensure teams deliver the right products in the right markets at the right time. They push the boundaries of the technology landscape to identify and deliver products into new and existing market opportunities.&lt;/p&gt;
&lt;p&gt;Our product managers are technology professionals with a software engineering background who strive to become business executives and entrepreneurs. We discuss strategy, plan product development, drive engagement, and promote the open source way. We oversee the entire product lifecycle from conception to delivery, blending technical expertise, strategic thinking, analytics, project management skills and effective communication to ensure products meet both user needs and business objectives.&lt;/p&gt;
&lt;p&gt;We have open product manager roles across a wide range of product domains, including:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Ubuntu Platform - Our Ubuntu experience on Desktop, Server, Windows (WSL), Multipass, Gaming, Enterprise, &amp;amp; Hardware Enablement&lt;/li&gt;
&lt;li&gt;Ubuntu Pro Services - Our key commercial offerings Ubuntu Pro, Compliance, Standards, Security Engineering, and Managed Services on cloud and on prem&lt;/li&gt;
&lt;li&gt;IoT - Ubuntu on embedded devices and/or edge servers, device management, and robotics&lt;/li&gt;
&lt;li&gt;Cloud - Ubuntu in public and private clouds, promoting automation frameworks, and including technologies such as Kubernetes, MAAS, and LXD&lt;/li&gt;
&lt;li&gt;Telco - Open source for Telco&#39;s including technologies and standards related to Core Network, RAN/vRAN, SoNIC, DENT, and SmartNICs&lt;/li&gt;
&lt;li&gt;Finance - Open source solutions for financial institutions including trading platforms, blockchain technologies, regulatory compliance, and AI-driven analytics&lt;/li&gt;
&lt;li&gt;Automotive - Open source solutions for autonomous driving, in-vehicle infotainment, connected vehicles, and compliance with automotive industry standards such as ISO 26262 and ISO 21434&lt;/li&gt;
&lt;li&gt;Application Management - Open source solutions in the enterprise including Observability, IAM, App Stores and technologies such Grafana, GitOps, and Juju Charms&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;If your domain of expertise isn’t listed above, yet you feel it’s relevant to Canonical, then feel free to apply anyway. We will route you to the most suitable team.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location:&lt;/strong&gt; These roles are home based in the EMEA time zone.&lt;/p&gt;
&lt;h3&gt;This role entails&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Lead the product development lifecycle, reviewing the priorities and goals for your product&lt;/li&gt;
&lt;li&gt;Collaborate with cross-functional teams such as engineering, design, marketing, and sales&lt;/li&gt;
&lt;li&gt;Address common challenges across projects, align on priorities, enable informed decisions, and keep business execution on track&lt;/li&gt;
&lt;li&gt;Conduct market research, analyse industry trends, and gather customer feedback to identify opportunities&lt;/li&gt;
&lt;li&gt;Communicate your product vision, status updates, and key decisions to ensure alignment and manage expectations&lt;/li&gt;
&lt;li&gt;Conduct usability testing, analyse user feedback, and iterate on the product to improve the user experience&lt;/li&gt;
&lt;li&gt;Collaborate with marketing, sales, and support teams to develop go-to-market strategies, create product documentation, and provide training&lt;/li&gt;
&lt;li&gt;Contribute to the success of our sales team in winning new opportunities, reviewing customer feedback and participating in customer meetings&lt;/li&gt;
&lt;li&gt;Guide and mentor a team of product managers, helping them grow in their roles and succeed in their projects&lt;/li&gt;
&lt;li&gt;Oversee the work of multiple product lines, ensuring consistency in strategy and execution across your team&lt;/li&gt;
&lt;li&gt;Facilitate collaboration and resolve conflicts within your team and across other departments&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What we are looking for in you&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Exceptional academic results at high school and university&lt;/li&gt;
&lt;li&gt;Understanding of Linux and the wider open source software community&lt;/li&gt;
&lt;li&gt;Understanding of computer architecture, application development, datacenters, cloud or devices&lt;/li&gt;
&lt;li&gt;Passion to write about technologies and the tech landscape&lt;/li&gt;
&lt;li&gt;A strong work ethic, and personal interests aligned with the open source movement&lt;/li&gt;
&lt;li&gt;Curiosity, and the habit of continuous learning&lt;/li&gt;
&lt;li&gt;A strong sense of ownership&lt;/li&gt;
&lt;li&gt;Problem solving and the ability to innovate&lt;/li&gt;
&lt;li&gt;Outstanding communications skills in English, both verbal and written&lt;/li&gt;
&lt;li&gt;For more senior positions, product management experience in the software industry&lt;/li&gt;
&lt;li&gt;Proven experience in managing and mentoring product managers or cross-functional teams&lt;/li&gt;
&lt;li&gt;Ability to manage multiple projects or product lines while maintaining focus on key priorities&lt;/li&gt;
&lt;li&gt;Demonstrated leadership in aligning diverse teams and driving consensus around product strategies&lt;/li&gt;
&lt;li&gt;Willingness to travel internationally up to 4 times a year for company events up to two weeks long&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Additional skills that we value&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Familiarity with a particular verticals (e.g. Telco, Finance, Industrial, Automotive)&lt;/li&gt;
&lt;li&gt;Familiarity with the technology ecosystem including Silicon, IHV, ISV, ODM/OEMs, cloud service providers and channel&lt;/li&gt;
&lt;li&gt;Familiarity with cloud native technologies such as Kubernetes, Docker containers &amp;amp; Snaps&lt;/li&gt;
&lt;li&gt;Familiarity with embedded and connected device technology and ecosystems&lt;/li&gt;
&lt;li&gt;Experience in managing distributed teams across different time zones&lt;/li&gt;
&lt;li&gt;Demonstrated ability to foster collaboration and innovation in team settings&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What we offer colleagues&lt;/h3&gt;
&lt;p&gt;We consider geographical location, experience, and performance in shaping compensation worldwide. We revisit compensation annually (and more often for graduates and associates) to ensure we recognise outstanding performance. In addition to base pay, we offer a performance-driven annual bonus or commission. We provide all team members with additional benefits, which reflect our values and ideals. We balance our programs to meet local needs and ensure fairness globally.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Distributed work environment with twice-yearly team sprints in person&lt;/li&gt;
&lt;li&gt;Personal learning and development budget of USD 2,000 per year&lt;/li&gt;
&lt;li&gt;Annual compensation review&lt;/li&gt;
&lt;li&gt;Recognition rewards&lt;/li&gt;
&lt;li&gt;Annual holiday leave&lt;/li&gt;
&lt;li&gt;Maternity and paternity leave&lt;/li&gt;
&lt;li&gt;Employee Assistance Program&lt;/li&gt;
&lt;li&gt;Opportunity to travel to new locations to meet colleagues&lt;/li&gt;
&lt;li&gt;Priority Pass, and travel upgrades for long haul company events&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;About Canonical&lt;/h3&gt;
&lt;p&gt;Canonical is a pioneering tech firm at the forefront of the global move to open source. As the company that publishes Ubuntu, one of the most important open source projects and the platform for AI, IoT and the cloud, we are changing the world of software. We recruit on a global basis and set a very high standard for people joining the company. We expect excellence - in order to succeed, we need to be the best at what we do. Most colleagues at Canonical have worked from home since its inception in 2004.​ Working here is a step into the future, and will challenge you to think differently, work smarter, learn new skills, and raise your game.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Canonical is an equal opportunity employer&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are proud to foster a workplace free from discrimination. Diversity of experience, perspectives, and background create a better work environment and better products. &lt;a href=&quot;https://canonical.com/careers/diversity/identity&quot;&gt;Whatever your identity, we will give your application fair consideration.&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;#LI-remote&lt;/p&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Us&lt;/h3&gt;
&lt;p&gt;At Cloudflare, we are on a mission to help build a better Internet. Today the company runs one of the world’s largest networks that powers millions of websites and other Internet properties for customers ranging from individual bloggers to SMBs to Fortune 500 companies. Cloudflare protects and accelerates any Internet application online without adding hardware, installing software, or changing a line of code. Internet properties powered by Cloudflare all have web traffic routed through its intelligent global network, which gets smarter with every request. As a result, they see significant improvement in performance and a decrease in spam and other attacks. Cloudflare was named to Entrepreneur Magazine’s Top Company Cultures list and ranked among the World’s Most Innovative Companies by Fast Company.&lt;/p&gt;
&lt;p&gt;At Cloudflare, we’re not looking for people who wait for a polished roadmap; we’re looking for the builders who see the cracks in the Internet that everyone else has simply learned to live with. We value candidates who have the instinct to spot a &quot;normalized&quot; problem and the AI-native curiosity to create a solution using the latest tools. Our culture is built on iteration, leveraging AI to ship faster today to make it better tomorrow, while ensuring that every improvement, no matter how small, is shared across the team to lift everyone up. If you’re the type of person who values curiosity over bureaucracy, and that AI is a partner in solving tough problems to keep the Internet moving forward, you’ll fit right in.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Available Locations- New York, London&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Cloudflare, we have our eyes set on an ambitious goal: to help build a better Internet. Today the company runs one of the world’s largest networks that powers trillions of requests per month. Cloudflare protects and accelerates any Internet application online without adding hardware, installing software, or changing a line of code. Internet properties powered by Cloudflare have all web traffic routed through its intelligent global network, which gets smarter with every request. As a result, they see significant improvement in performance and a decrease in spam and other attacks. Cloudflare was recognized by the World Economic Forum as a Technology Pioneer and named to Entrepreneur Magazine’s Top Company Cultures list.&lt;/p&gt;
&lt;p&gt;We realize people do not fit into neat boxes. We are looking for curious and empathetic individuals who are committed to developing themselves and learning new skills, and we are ready to help you do that. We cannot complete our mission without building a diverse and inclusive team. We hire the best people based on an evaluation of their potential and support them throughout their time at Cloudflare. Come join us!&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Cloudflare’s Engineering Team is home to some of the industry’s top engineers, dedicated to building and scaling innovative software that handles a huge proportion of the Internet. Our Detection department sits at the heart of that mission: we identify automated, fraudulent, and malicious activity across the Internet and through our gateway. We develop advanced detection systems and machine learning models that operate at scale, collaborating with Product and Engineering teams across the company to protect our customers and stay ahead of the constantly evolving threat landscape.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead the research, design, and evaluate detection models that identify automated, fraudulent, and malicious activity across Internet-scale data&lt;/li&gt;
&lt;li&gt;Mentor others in how to uncover patterns and behaviors that distinguish adversaries from legitimate users.&lt;/li&gt;
&lt;li&gt;Own the detection measurement framework, defining metrics and evaluation strategies for problems where ground truth is noisy, delayed, or contested.&lt;/li&gt;
&lt;li&gt;Drive adoption of promising AI/ML techniques and represent Cloudflare in the broader research community.&lt;/li&gt;
&lt;li&gt;Drive cross-functional partnerships with ML Engineers, Data Engineers, and Product; Influence roadmaps and align detection strategy with company priorities.&lt;/li&gt;
&lt;li&gt;Shape long-term detection strategy, identifying gaps and opportunities that span multiple product areas.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Desirable Skills, Knowledge, and Experience&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Fraud and bots at scale.&lt;/strong&gt; You have experience across fraud, abuse, and/or bot detection on large, high-velocity traffic. You may focus on one, but you transfer instincts between them.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Strong fundamentals, fluent in data.&lt;/strong&gt; You have solid applied statistics, machine learning, and AI methodology fundamentals. You choose the right technique for the problem, and are fluent with large-scale data.&lt;/li&gt;
&lt;li&gt;You have at least 8-10 years of experience professionally working in Data Science, ML Engineering, or Software Engineering.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Demonstrated ability to make ambiguous, high-stakes technical decisions with incomplete information.&lt;/li&gt;
&lt;li&gt;You are very comfortable with Python &amp;amp; SQL in production environments.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus points&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;At home in ground truth ambiguity.&lt;/strong&gt; Building detections when ground truth is scarce is the heart of this job. You make real progress with weak, delayed, or absent labels and you&#39;re energized by adversaries that fight back.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You don&#39;t burn signals.&lt;/strong&gt; You understand (or are curious to learn) how to act on detections without tipping your hand, knowing that how you deploy and respond can erode your future visibility.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Pragmatic about complexity.&lt;/strong&gt; You know when a simple solution beats a complex one, and you don&#39;t chase small gains at disproportionate cost.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Disciplined in code.&lt;/strong&gt; You apply strong programming and engineering best practices in both research and production code.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Impact-driven and clear.&lt;/strong&gt; You connect your work to business impact and communicate clearly across technical and non-technical stakeholders.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Compensation may be adjusted depending on work location.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&amp;nbsp;For New York City based hires: Estimated annual salary of $215,000 - $270,000.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Equity&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;This role is eligible to participate in Cloudflare’s equity plan.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Cloudflare offers a complete package of benefits and programs to support you and your family.&amp;nbsp; Our benefits programs can help you pay health care expenses, support caregiving, build capital for the future and make life a little easier and fun!&amp;nbsp; The below is a description of our benefits for employees in the United States, and benefits may vary for employees based outside the U.S.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Health &amp;amp; Welfare Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Medical/Rx Insurance&lt;/li&gt;
&lt;li&gt;Dental Insurance&lt;/li&gt;
&lt;li&gt;Vision Insurance&lt;/li&gt;
&lt;li&gt;Flexible Spending Accounts&lt;/li&gt;
&lt;li&gt;Commuter Spending Accounts&lt;/li&gt;
&lt;li&gt;Fertility &amp;amp; Family Forming Benefits&lt;/li&gt;
&lt;li&gt;On-demand mental health support and Employee Assistance Program&lt;/li&gt;
&lt;li&gt;Global Travel Medical Insurance&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Financial Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Short and Long Term Disability Insurance&lt;/li&gt;
&lt;li&gt;Life &amp;amp; Accident Insurance&lt;/li&gt;
&lt;li&gt;401(k) Retirement Savings Plan&lt;/li&gt;
&lt;li&gt;Employee Stock Participation Plan&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Time Off&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Flexible paid time off covering vacation and sick leave&lt;/li&gt;
&lt;li&gt;Leave programs, including parental, pregnancy health, medical, and bereavement leave&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;What Makes Cloudflare Special?&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re not just a highly ambitious, large-scale technology company. We’re a highly ambitious, large-scale technology company with a soul. Fundamental to our mission to help build a better Internet is protecting the free and open Internet.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://blog.cloudflare.com/protecting-free-expression-online/&quot;&gt;&lt;strong&gt;Project Galileo&lt;/strong&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;: Since 2014, we&#39;ve equipped more than 2,400 journalism and civil society organizations in 111 countries with powerful tools to defend themselves against attacks that would otherwise censor their work, technology already used by Cloudflare’s enterprise customers--at no cost.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;https://www.cloudflare.com/athenian/&quot;&gt;Athenian Project&lt;/a&gt;&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;: In 2017, we created the Athenian Project to ensure that state and local governments have the highest level of protection and reliability for free, so that their constituents have access to election information and voter registration. Since the project, we&#39;ve provided services to more than 425 local government election websites in 33 states.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://1.1.1.1/&quot;&gt;&lt;strong&gt;1.1.1.1&lt;/strong&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;: We released&lt;/span&gt;&lt;a href=&quot;https://1.1.1.1/&quot;&gt; &lt;span style=&quot;font-weight: 400;&quot;&gt;1.1.1.1&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; to help fix the foundation of the Internet by building a faster, more secure and privacy-centric public DNS resolver. This is available publicly for everyone to use - it is the first consumer-focused service Cloudflare has ever released. Here’s the deal - we don’t store client IP addresses never, ever. We will continue to abide by our&lt;/span&gt;&lt;a href=&quot;https://developers.cloudflare.com/1.1.1.1/privacy/public-dns-resolver&quot;&gt; privacy commitment&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; and ensure that no user data is sold to advertisers or used to target consumers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Sound like something you’d like to be a part of? We’d love to hear from you!&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Please note that applicants who progress to the offer stage of the interview process may be asked to attend an in-person interview within one of the Cloudflare Offices or Cloudflare Hubs.&amp;nbsp; More details about this will be available at that stage of the interview process.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;This position may require access to information protected under U.S. export control laws, including the U.S. Export Administration Regulations. Please note that any offer of employment may be conditioned on your authorization to receive software or technology controlled under these U.S. export laws without sponsorship for an export license.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Cloudflare is proud to be an equal opportunity employer. &amp;nbsp;We are committed to providing equal employment opportunity for all people and place great value in both diversity and inclusiveness. &amp;nbsp;All qualified applicants will be considered for employment without regard to their, or any other person&#39;s, perceived or actual&lt;/span&gt; &lt;span style=&quot;font-weight: 400;&quot;&gt;race, color, religion, sex, gender, gender identity, gender expression, sexual orientation, national origin, ancestry, citizenship, age, physical or mental disability, medical condition, family care status, or any other basis protected by law. &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We are an AA/Veterans/Disabled Employer.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Cloudflare provides reasonable accommodations to qualified individuals with disabilities. &amp;nbsp;Please tell us if you require a reasonable accommodation to apply for a job. Examples of reasonable accommodations include, but are not limited to, changing the application process, providing documents in an alternate format, using a sign language interpreter, or using specialized equipment. &amp;nbsp;If you require a reasonable accommodation to apply for a job, please contact us via e-mail at &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;hr@cloudflare.com&lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; or via mail at 101 Townsend St. San Francisco, CA 94107.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

&lt;p&gt;The Product Management team drives Asana’s product strategy and execution, translating customer needs and opportunities into a compelling roadmap and working cross-functionally to deliver impactful solutions for team productivity and collaboration. We’re helping to define the Work Management category and inventing new ways for teams to work more efficiently together and see the larger purpose behind their work. Our team works directly with Engineering, Design, Experience Research, and Data Science, as well as with Sales, Support, and Marketing to ship great products. You’ll take part in every type of product work here — from strategy to product to process improvements — conceptualizing, launching, and iterating on Asana itself for millions of teams around the world.&lt;br&gt;&lt;br&gt;We are looking for an experienced product manager to join the team responsible for key elements of Asana’s work platform strategy. Over the next 2 years, a critical piece of Asana’s strategy is to continue building out a platform that can support many different types of workflows. You’ll be responsible for understanding how customers’ need to structure work to enable their workflows and build out the features to meet those needs directly, and enable other Asana R&amp;amp;D teams to incorporate structure into their features. You’ll work with a large set of cross-functional partners across both our GTM and internal teams to learn about how internal and external customers of all sizes need to customize their core Asana experience to support their workflows, and how your work fits within the entire customer lifecycle so that we customers feel confident in structuring their work in the right way at the right time to power.&lt;/p&gt;
&lt;p&gt;This role is perfect for a product manager with deep customer empathy for the complexity of mapping messy work to a structured tool, has an end-to-end ownership mindset, and drives for results. We are looking for someone who has experience building software in partnership with enterprise customers, strong product intuition, and can marry qualitative insights with quantitative data to deeply understand the customer experience. You thrive on learning from customers, and are excited to partner with engineering, design, user research, sales, and the rest of our amazing PM team.&lt;/p&gt;
&lt;p&gt;This role is based in our Warsaw office with an office-centric hybrid schedule. The standard in-office days are Monday, Tuesday, and Thursday. Most Asanas have the option to work from home on Wednesdays. Working from home on Fridays depends on the type of work you do and the teams with which you partner. If you&#39;re interviewing for this role, your recruiter will share more about the in-office requirements.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll achieve&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Define and deliver a compelling roadmap to ensure customers have the structure they need to power their end to end workflows.Synthesize input from customers, user research, data science, and business partners, ensuring we are continuously investing in the right ways to structure work, and shifting quickly when an area is no longer leveraged.Take new initiatives from 0 to 1, and then scale them up, as we validate product market fitPartner closely with design, engineering, marketing, and customer success to co-create a cohesive end to end journey and execute on the roadmap with velocity.Collaborate across the R&amp;amp;D organization to support other R&amp;amp;D teams in achieving their goals.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About you&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of experience as a Product Manager, with at least 1-2 years experience on B2B SaaS.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Customer-centric:&lt;/strong&gt; You spend time directly with customers to understand their nuanced challenges and synthesizing research to identify and solve problems..&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Communication and collaboration:&lt;/strong&gt; Demonstrate strong communication and collaboration skills with cross-functional teams, clarifying complex concepts and writing precise product specifications. You pair effectively with design, engineering, and our business teams.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Systems thinker: &lt;/strong&gt;&lt;strong&gt;Think systemically, creating solutions that simplify complex use cases for customers.&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Strategic:&lt;/strong&gt; Provide strategic insights and create intuitive connections within the custom field &amp;amp; types features and platform to address critical customer issues.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Get Stuff Done: &lt;/strong&gt;Execute projects with high velocity, breaking them down into MVPs and iterative stages for impactful delivery.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Grow Team Asana:&lt;/strong&gt; Foster team morale and share best practices in product management.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Growth Mindset:&lt;/strong&gt; Embrace a growth mindset, welcoming feedback and maintaining curiosity in learning.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;At Asana, we&#39;re committed to building teams that include a variety of backgrounds, perspectives, and skills, as this is critical to helping us achieve our mission. If you&#39;re interested in this role and don&#39;t meet every listed requirement, we still encourage you to apply.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What we’ll offer&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our comprehensive compensation package plays a big part in how we recognize you for the impact you have on our path to achieving our mission. We believe that compensation should be reflective of the value you create relative to the market value of your role. To ensure pay is fair and not impacted by biases, we&#39;re committed to looking at market value which is why we check ourselves and conduct a yearly pay equity audit.&lt;/p&gt;
&lt;p&gt;For this role, the estimated base salary range is between 29,000 - 31,935PLN. The actual base salary will vary based on various factors, including market and individual qualifications objectively assessed during the interview process. The listed range above is a guideline, and the base salary range for this role may be modified.&lt;/p&gt;
&lt;p&gt;In addition to base salary, your compensation package may include additional components such as equity, sales incentive pay (for most sales roles), and benefits. If you&#39;re interviewing for this role, speak with your Talent Acquisition Partner to learn more about the total compensation and benefits for this role.&lt;/p&gt;
&lt;p&gt;We strive to provide equitable and competitive benefits packages that support our employees worldwide and include:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Mental health, wellness &amp;amp; fitness benefits&lt;/li&gt;
&lt;li&gt;Career coaching &amp;amp; support&lt;/li&gt;
&lt;li&gt;Inclusive family building benefits&lt;/li&gt;
&lt;li&gt;Long-term savings or retirement plans&lt;/li&gt;
&lt;li&gt;In-office culinary options to cater to your dietary preferences&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;These are just some of the benefits we offer, and benefits may vary based on role, country, and local regulations. If you&#39;re interviewing for this role, speak with your Talent Acquisition Partner to learn more about the total compensation and benefits for this role.&lt;/p&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About us&lt;/strong&gt;&lt;/p&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;Asana is a leading platform for human + AI collaboration. Millions of teams around the world rely on Asana to achieve their most important goals, faster. Asana has been named to Fortune&#39;s Best Workplaces for 7+ years and recognized by Fast Company, Forbes, and Gartner for excellence in workplace culture and innovation. We offer an exceptional office-centric culture while adopting the best elements of hybrid models to ensure that every one of our global team members can work together effortlessly. With 13+ offices all over the world, we are always looking for individuals who care about building technology that drives positive change in the world and a culture where everyone feels that they belong.&lt;/p&gt;
&lt;div class=&quot;TypographyPresentation_31345133_root TypographyPresentation_31345133_root--medium RichText3-paragraph--withVSpacingNormal RichText3-paragraph HighlightSol_1625403506_highlightSol HighlightSol_1625403506_buildingBlock&quot; style=&quot;text-align: left;&quot;&gt;We believe in supporting people to do their best work and thrive. Our goal is to ensure that Asana upholds an environment where all people feel that they are respected and valued, whether they are applying for an open position or working at the company. We provide equal employment opportunities to all applicants without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other characteristic protected by law.&lt;/div&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;&lt;strong&gt;&lt;a class=&quot;LinkThemeablePresentation LinkPrimaryPresentation LinkPrimaryPresentation--sentimentSelected PrimaryLink HighlightSol HighlightSol--core HighlightSol--buildingBlock&quot; href=&quot;https://www.gem.com/form?formID=fbcdec8c-3442-43b9-9b45-d2b5f4ea25db&quot; target=&quot;_blank&quot;&gt;Join Asana’s Talent Network&lt;/a&gt;&lt;/strong&gt;&amp;nbsp;to stay up to date on job opportunities and life at Asana.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;Join us in building the future of finance.&lt;/h2&gt;
&lt;p&gt;Our mission is to democratize finance for all. &lt;a href=&quot;https://www.cerulli.com/press-releases/cerulli-anticipates-124-trillion-in-wealth-will-transfer-through-2048&quot; target=&quot;_blank&quot;&gt;An estimated $124 trillion of assets&lt;/a&gt; will be inherited by younger generations in the next two decades. The largest transfer of wealth in human history. If you’re ready to be at the epicenter of this historic cultural and financial shift, keep reading.&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;&lt;strong&gt;About the team + role&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;We are building an elite team, applying frontier technologies to the world’s biggest financial problems. We’re looking for bold thinkers. Sharp problem-solvers. Builders who are wired to make an impact. Robinhood isn’t a place for complacency, it’s where ambitious people do the best work of their careers. We’re a high-performing, fast-moving team with ethics at the center of everything we do. Expectations are high, and so are the rewards.&lt;/p&gt;
&lt;p&gt;The Talent Management &amp;amp; Analytics team is scaling to its next major milestone—integrating advanced predictive insights and tactical AI into our workforce systems. Our mission is to build the data solutions that help the entire company recruit exceptional talent, design high-performing team structures, and put active organizational insights directly into the hands of everyone making team decisions. Operating at the intersection of data science, product development, and organizational psychology, we are transforming how Robinhood uses data to empower our workforce and anticipate organizational needs.&lt;/p&gt;
&lt;p&gt;As a Staff Data Scientist, you will serve as the team&#39;s technical and strategic anchor, owning the vision, design, and delivery of the high-impact data products that our executives, people partners, and line managers rely on every day. Your focus will be entirely on solving meaningful organizational problems: understanding what enables exceptional talent to thrive, accelerating team performance, and designing proactive strategies that support long-term retention across Robinhood. This is a unique opportunity to apply state-of-the-art language models and predictive analytics to solve critical talent problems!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;This role is based in our Menlo Park, CA, Chicago, IL, and New York, NY offices, with in-person attendance expected at least 3 days per week.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Robinhood, we believe in the power of in-person work to accelerate progress, spark innovation, and strengthen community. Our office experience is intentional, energizing, and designed to fully support high-performing teams.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Spearhead the next phase of talent intelligence:&lt;/strong&gt; Take the team beyond descriptive reporting and build the predictive frameworks that show not just what is happening in our workforce, but what will happen next.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Architect a unified workforce data model:&lt;/strong&gt; Pipeline data across disparate recruiting systems, performance cycles, surveys, and internal tools into a single, cohesive data model that maps the entire employee lifecycle; use AI-native workflows aggressively to parse unstructured text like exit notes and survey feedback at scale.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Define the metrics dictionary and semantic layer:&lt;/strong&gt; Standardize how metrics like headcount, attrition, and workforce trends are measured across the company; build the semantic layers that keep this data consistent and trustworthy at scale.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Drive data access control and governance:&lt;/strong&gt; Build the frameworks for role-based access controls and data masking so HR, Finance, and line managers have exactly the access they need without risking sensitive personnel data.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Redesign employee sentiment architecture:&lt;/strong&gt; Replace traditional annual survey cycles with a continuous, always-on listening framework that captures real-time organizational health and highlights leading risk indicators.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Own product delivery:&lt;/strong&gt; Act as the technical product owner for internal data interfaces—collaborating directly with Enterprise Engineering to ensure exceptional user utility, predictive accuracy, and data reliability.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Enforce rigorous statistical standards:&lt;/strong&gt; Apply experimental design, A/B testing, and psychometric methodologies to ensure our predictive workforce models and survey frameworks are scientifically backed and statistically valid.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;What you bring&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;7+ years of data science experience, with advanced skills in Python, SQL, and direct experience with modern data infrastructure like Snowflake, BigQuery, or dbt.&lt;/li&gt;
&lt;li&gt;Strong product focus and experience defining user requirements, collaborating with engineers, and taking internal data tools from conception to launch.&lt;/li&gt;
&lt;li&gt;Deep understanding of statistics, experimental design, and psychometrics or survey methodology to design research-backed questions.&lt;/li&gt;
&lt;li&gt;Direct experience integrating language models into data pipelines to automate text processing and summarization at scale.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;What we offer&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Challenging, high-impact work to grow your career.&lt;/li&gt;
&lt;li&gt;Performance-driven compensation with multipliers for outsized impact, bonus programs, equity ownership, and 401(k) matching.&lt;/li&gt;
&lt;li&gt;Best-in-class benefits to fuel your work, including 100% paid health insurance for employees with 90% coverage for dependents.&lt;/li&gt;
&lt;li&gt;Lifestyle wallet — a highly flexible benefits spending account for wellness, learning, and more.&lt;/li&gt;
&lt;li&gt;Employer-paid life &amp;amp; disability insurance, fertility benefits, and mental health benefits.&lt;/li&gt;
&lt;li&gt;Time off to recharge including company holidays, paid time off, sick time, parental leave, and more!&lt;/li&gt;
&lt;li&gt;Exceptional office experience with catered meals, events, and comfortable workspaces.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;strong&gt;In addition to the base pay range listed below, this role is also eligible for bonus opportunities + equity + benefits.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Base pay for the successful applicant will depend on a variety of job-related factors, which may include education, training, experience, location, business needs, or market demands. The expected base pay range for this role is based on the location where the work will be performed and is aligned to one of 3 compensation zones. For other locations not listed, compensation can be discussed with your recruiter during the interview process.&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Base Pay Range:&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Zone 1 (Menlo Park, CA; New York, NY; Bellevue, WA; Washington, DC)&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$217,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$255,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Zone 2 (Denver, CO; Westlake, TX; Chicago, IL)&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$191,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$224,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Zone 3 (Lake Mary, FL; Clearwater, FL; Gainesville, FL)&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$170,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$199,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Click &lt;a href=&quot;https://careers.robinhood.com/benefits&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt; to learn more about our Total Rewards, which vary by region and entity.&lt;/p&gt;
&lt;p&gt;If our mission energizes you and you’re ready to build the future of finance, we look forward to seeing your application.&lt;/p&gt;
&lt;p&gt;Robinhood provides equal opportunity for all applicants, offers reasonable accommodations upon request, and complies with applicable equal employment and privacy laws. Inclusion is built into how we hire and work—welcoming different backgrounds, perspectives, and experiences so everyone can do their best. Please review the&amp;nbsp;&lt;a href=&quot;https://careers.robinhood.com/applicantprivacypolicy&quot; target=&quot;_blank&quot;&gt;Privacy Policy&lt;/a&gt; for your country of application.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About Clarity AI &lt;/strong&gt;🪴&lt;/p&gt;
&lt;p&gt;Clarity AI is a global tech company founded in 2017 with a unique mission: &lt;strong&gt;bringing societal impact to markets.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We leverage AI and machine learning technologies to provide &lt;strong&gt;top international&lt;/strong&gt; &lt;strong&gt;investors, governments, companies, and consumers&lt;/strong&gt; with the right data, methodologies, and tools to make more informed decisions.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are now a team of more than &lt;strong&gt;300 highly passionate and curious individuals&lt;/strong&gt; from all over the world, with offices in New York, Madrid, London, Paris, and Abu Dhabi. Together, we have established Clarity AI as a &lt;strong&gt;leading sustainability tech AI company&lt;/strong&gt; backed by investors and strategic partners such as &lt;strong&gt;BlackRock, SoftBank, and Deutsche Börse&lt;/strong&gt;, who believe in us and share our goals.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are dedicated to cultivating an exceptional workplace environment, and we take pride in our culture, defined by our commitment to being&lt;strong&gt; fact-based, diverse, transparent, meritocratic, and flexible.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We have plans to continue growing our teams globally, so if you would like to join us on this rocket ship, keep reading! Your work will shape and guide the sustainable decisions of investors, companies and consumers worldwide.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About The Role &lt;/strong&gt;💻&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are looking for a&lt;strong&gt; Data Scientist &lt;/strong&gt;with a strong scientific mindset and relevant experience to help us bring societal impacts to market and make a difference. You would be part of a team of +20 international Data Scientists coming&amp;nbsp; from top Academic Institutions and Tech Companies with a shared passion for data science and a growing mindset.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;For more insight into the technologies used by the engineering team at Clarity AI, please explore our &lt;a href=&quot;https://stackshare.io/companies/clarity-ai&quot;&gt;Tech Stack&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Be Doing &lt;/strong&gt;🚀&lt;/p&gt;
&lt;p&gt;Working as a &lt;strong&gt;Data Scientist&amp;nbsp; &lt;/strong&gt;you will be responsible for:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Monitoring and maintaining machine learning and other data science products already in production.&lt;/li&gt;
&lt;li&gt;Building end-to-end machine learning models, Large Language Models (LLMs), and agent systems that deliver transparent, accurate sustainability data to our customers.&lt;/li&gt;
&lt;li&gt;Analyzing complex data sets autonomously&lt;/li&gt;
&lt;li&gt;Participating in the development of proofs of concept&lt;/li&gt;
&lt;li&gt;Keeping always an eye on the business needs &amp;amp; opportunities.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Communicating with a diverse set of stakeholders with different backgrounds&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Location 🌍&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The role is based in our tech hub in Madrid, Spain, but we are remote-friendly and open to the CET timezone +/- 2 hours.&lt;/p&gt;
&lt;p&gt;Way of Working: Remote/Hybrid&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Need &lt;/strong&gt;👀&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;2 years of experience working in Data Science products or PhD in ML / Applied Math / Quantitative Research / Statistics / Computer Science … or any related field.&lt;/li&gt;
&lt;li&gt;High level in the Python data science ecosystem (Pandas, Matplotlib, Scikit-Learn, …)&lt;/li&gt;
&lt;li&gt;At least well acquainted with working in collaborative code bases (Git) and production code (beyond notebooks)&lt;/li&gt;
&lt;li&gt;Solid software engineering fundamentals (testing, code review, design, performance).&lt;/li&gt;
&lt;li&gt;Experience with LLM/Agent prompt/retrieval design, vector databases, tool use/agents, evaluation and safety/guardrails.&lt;/li&gt;
&lt;li&gt;You care about sustainability and impact&lt;/li&gt;
&lt;li&gt;You are willing to learn and share your own learnings&lt;/li&gt;
&lt;li&gt;You are transparent and care about communicating effectively and constructively&lt;/li&gt;
&lt;li&gt;Highly motivated, independent and deeply passionate about making an impact with data &amp;amp; science&lt;/li&gt;
&lt;li&gt;Excellent oral and written English communication skills (minimum C1 level-proficient user)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Nice To Have ✨&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience in a start-up&lt;/li&gt;
&lt;li&gt;MSc/PhD degree in CS/EE/STEM or related field&lt;/li&gt;
&lt;li&gt;Experience with fintech/data products or sustainability/ESG domains.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What We Offer&lt;/strong&gt; 🥁&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Competitive compensation,&lt;/strong&gt; both in terms of base salary as well as equity plans that enable to you to share in our success&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Flexibility &lt;/strong&gt;in ways of working both in terms of your schedule as well as your location, whether you prefer to work from home, the office, or abroad with access to a global network of co-working spaces&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Generous paid time off schemes&lt;/strong&gt;, including vacation, sabbatical, religious observance and compensation days&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Meaningful benefits &lt;/strong&gt;including private healthcare coverage, fitness and wellness programs covered through Wellhub, working-from-home allowances to help you set up your home office and cover monthly expenses&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Professional development &lt;/strong&gt;with annual training budget for conferences, courses, certifications and access to top market e-learning platforms&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Collaborative environment &lt;/strong&gt;with multiple offices around the globe, regular team activities and events as well as employee-led resource groups&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;More About Clarity AI &lt;/strong&gt;&lt;strong&gt;⭐&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Clarity AI’s &lt;strong&gt;Founder and CEO, Rebeca Minguela&lt;/strong&gt;, is a successful entrepreneur who has been recognised by prestigious institutions like the World Economic Forum as one of the most distinguished leaders under 40.&lt;/p&gt;
&lt;p&gt;The leadership team has an international presence and is composed of professionals from leading tech, consulting, and banking firms, entrepreneurs, PhDs from top research institutions, and MBA graduates from top business schools.&lt;/p&gt;
&lt;p&gt;Clarity AI has received several awards:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;The Forrester New Wave&lt;/strong&gt; - ESG Ratings, Data, and Analytics - Leaders for 2022-2024&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Investment Week&lt;/strong&gt; - Best Sustainable Investment Research &amp;amp; Ratings Provider 2023&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Fast Company&lt;/strong&gt; - Most Innovative Companies 2023&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;European Commission | EU Seal of Excellence 2020 &lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;World Economic Forum&lt;/strong&gt; - Technology Pioneer 2020&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;World Economic Forum, Young Global Leader - Rebeca Minguela&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Clarity AI believes diversity, inclusion, and belonging are essential for creating an innovative and successful workplace. By actively promoting and engaging in sustainability efforts, we can help create a more equitable and resilient future for our planet and all its inhabitants.&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;&lt;strong&gt;About Anthropic&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Anthropic’s mission is to create reliable, interpretable, and steerable AI systems. We want AI to be safe and beneficial for our users and for society as a whole. Our team is a quickly growing group of committed researchers, engineers, policy experts, and business leaders working together to build beneficial AI systems.&lt;/p&gt;&lt;/div&gt;&lt;h2 class=&quot;heading&quot;&gt;&lt;strong&gt;About the role&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;As an Applied AI team member at Anthropic, you will be a Pre-Sales architect focused on becoming a trusted technical advisor helping large enterprises understand the value of Claude and paint the vision on how they can successfully integrate and deploy Claude into their technology stack. You&#39;ll combine your deep technical expertise with customer-facing skills to architect innovative LLM solutions that address complex business challenges while maintaining our high standards for safety and reliability.&lt;/p&gt;
&lt;p&gt;Working closely with our Sales, Product, and Engineering teams, you&#39;ll guide customers from initial technical discovery through successful deployment. You&#39;ll leverage your expertise to help customers understand Claude&#39;s capabilities, develop evals, and design scalable architectures that maximize the value of our AI systems.&lt;/p&gt;
&lt;h2 class=&quot;heading&quot;&gt;&lt;strong&gt;Key responsibilities&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partner with account executives across Japan to deeply understand customer requirements and translate them into technical solutions, ensuring alignment between business objectives and technical implementation&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Serve as the primary technical advisor to enterprise customers across Japan throughout their Claude adoption journey, from discovery to initial evaluation through deployment. You will need to coordinate internally across multiple teams &amp;amp; stakeholders to drive customer success&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Support customers building with both the Claude API and Claude for Work&amp;nbsp;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Create and deliver compelling technical content tailored to different audiences across Japan. You will need to be able to spread the gamut from technical deep dives for engineering &amp;amp; development teams up to business value focused conversations with executives&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Guide technical architecture decisions and help customers across Japan integrate Claude effectively into their existing technology stack&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Help customers develop evaluation frameworks to measure Claude&#39;s performance for their specific use cases&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Identify common integration patterns and contribute insights back to our Product and Engineering teams&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Travel occasionally to customer sites for workshops, technical deep dives, and relationship building&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Maintain strong knowledge of the latest developments in LLM capabilities and implementation patterns&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;heading&quot;&gt;&lt;strong&gt;Minimum qualifications&lt;br&gt;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Experience in technical customer-facing roles such as Solutions Architect, Sales Engineer, or Technical Account Manager&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Native-level Japanese fluency and business-level English required&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience working with enterprise customers, navigating complex buying cycles involving multiple stakeholders&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Exceptional ability to build relationships with and communicate technical concepts to diverse stakeholders to include C-suite executives, engineering &amp;amp; IT teams, and more&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Strong technical communication skills with the ability to translate customer requirements between technical and business stakeholders&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;heading&quot;&gt;&lt;strong&gt;Preferred qualifications&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;5+ years of relevant experience&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience designing scalable cloud architectures and integrating with enterprise systems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Comfortable with python&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Familiarity with common LLM frameworks and tools or a background in machine learning or data science&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Excitement for engaging in cross-organizational collaboration, working through trade-offs, and balancing competing priorities&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;A love of teaching, mentoring, and helping others succeed&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Excellent communication and interpersonal skills, able to convey complicated topics in easily understandable terms to a diverse set of external and internal stakeholders. You enjoy engaging in cross-organizational collaboration, working through trade-offs, and balancing competing priorities&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Passion for thinking creatively about how to use technology in a way that is safe and beneficial, and ultimately furthers the goal of advancing safe AI systems&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h2&gt;&lt;strong&gt;Logistics&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;Minimum education: &lt;/strong&gt;Bachelor’s degree or an equivalent combination of education, training, and/or experience&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Required field of study:&amp;nbsp;&lt;/strong&gt;A field relevant to the role as demonstrated through coursework, training, or professional experience&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Minimum years of experience: &lt;/strong&gt;Years of experience required will correlate with the internal job level requirements for the position&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location-based hybrid policy:&lt;/strong&gt; Currently, we expect all staff to be in one of our offices at least 25% of the time. However, some roles may require more time in our offices.&lt;/p&gt;
&lt;p&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Visa sponsorship:&lt;/strong&gt;&amp;nbsp;We do sponsor visas! However, we aren&#39;t able to successfully sponsor visas for every role and every candidate. But if we make you an offer, we will make every reasonable effort to get you a visa, and we retain an immigration lawyer to help with this.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We encourage you to apply even if you do not believe you meet every single qualification.&lt;/strong&gt; Not all strong candidates will meet every single qualification as listed.&amp;nbsp; Research shows that people who identify as being from underrepresented groups are more prone to experiencing imposter syndrome and doubting the strength of their candidacy, so we urge you not to exclude yourself prematurely and to submit an application if you&#39;re interested in this work. We think AI systems like the ones we&#39;re building have enormous social and ethical implications. We think this makes representation even more important, and we strive to include a range of diverse perspectives on our team.&lt;br&gt;&lt;br&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Your safety matters to us.&lt;/strong&gt; To protect yourself from potential scams, remember that Anthropic recruiters only contact you from&amp;nbsp;@anthropic.com&amp;nbsp;email addresses. In some cases, we may partner with vetted recruiting agencies who will identify themselves as working on behalf of Anthropic. Be cautious of emails from other domains. Legitimate Anthropic recruiters will never ask for money, fees, or banking information before your first day. If you&#39;re ever unsure about a communication, don&#39;t click any links—visit&amp;nbsp;&lt;u data-stringify-type=&quot;underline&quot;&gt;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;http://anthropic.com/careers&quot; target=&quot;_blank&quot; data-stringify-link=&quot;http://anthropic.com/careers&quot; data-sk=&quot;tooltip_parent&quot; data-remove-tab-index=&quot;true&quot;&gt;anthropic.com/careers&lt;/a&gt;&lt;/u&gt;&amp;nbsp;directly for confirmed position openings.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;How we&#39;re different&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;We believe that the highest-impact AI research will be big science. At Anthropic we work as a single cohesive team on just a few large-scale research efforts. And we value impact — advancing our long-term goals of steerable, trustworthy AI — rather than work on smaller and more specific puzzles. We view AI research as an empirical science, which has as much in common with physics and biology as with traditional efforts in computer science. We&#39;re an extremely collaborative group, and we host frequent research discussions to ensure that we are pursuing the highest-impact work at any given time. As such, we greatly value communication skills.&lt;/p&gt;
&lt;p&gt;The easiest way to understand our research directions is to read our recent research. This research continues many of the directions our team worked on prior to Anthropic, including: GPT-3, Circuit-Based Interpretability, Multimodal Neurons, Scaling Laws, AI &amp;amp; Compute, Concrete Problems in AI Safety, and Learning from Human Preferences.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Come work with us!&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Anthropic is a public benefit corporation headquartered in San Francisco. We offer competitive compensation and benefits, optional equity donation matching, generous vacation and parental leave, flexible working hours, and a lovely office space in which to collaborate with colleagues. &lt;strong data-stringify-type=&quot;bold&quot;&gt;Guidance on Candidates&#39; AI Usage:&lt;/strong&gt;&amp;nbsp;Learn about&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://www.anthropic.com/candidate-ai-guidance&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.anthropic.com/candidate-ai-guidance&quot; data-sk=&quot;tooltip_parent&quot;&gt;our policy&lt;/a&gt; for using AI in our application process.&lt;/p&gt;&lt;/div&gt;

&lt;h4&gt;&lt;strong&gt;About the Job:&lt;/strong&gt;&lt;/h4&gt;
&lt;p data-renderer-start-pos=&quot;6723&quot; data-local-id=&quot;710549b6b17f&quot;&gt;LaunchDarkly is looking for a Data Analyst to join our Data &amp;amp; Analytics team in Ireland. In this role, you will focus on building and scaling reliable data models, automating reporting, and supporting global analytics delivery.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;6950&quot; data-local-id=&quot;79d9e5afb633&quot;&gt;You will partner closely with the Senior Data Analyst (Revenue &amp;amp; Metrics), Data Engineering, and business stakeholders to translate business logic into clean, scalable datasets. This role plays a key part in ensuring that defined metrics (e.g., ARR, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;NRR&lt;/span&gt;) are consistently implemented, automated, and delivered across the organization.&lt;/p&gt;
&lt;h4&gt;Responsibilities:&lt;/h4&gt;
&lt;p data-renderer-start-pos=&quot;7320&quot; data-local-id=&quot;a3c226227b49&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Data Modeling &amp;amp; Transformation&lt;/strong&gt;&lt;br&gt;Build and maintain scalable data models using modern tools (e.g., Snowflake, dbt). Translate defined business logic (e.g., ARR calculations) into clean and reusable datasets.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7528&quot; data-local-id=&quot;0a3409a01131&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Metrics Implementation&lt;/strong&gt;&lt;br&gt;Implement and maintain standardized metrics (e.g., ARR, &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;NRR&lt;/span&gt;, churn) in the data layer. Ensure consistency across dashboards and reports.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7690&quot; data-local-id=&quot;2eb74f43fbc0&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Automation &amp;amp; Pipeline Support&lt;/strong&gt;&lt;br&gt;Work with Data Engineering to automate data pipelines and reduce manual reporting processes.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7815&quot; data-local-id=&quot;a544a38c82ba&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Dashboarding &amp;amp; Reporting&lt;/strong&gt;&lt;br&gt;Develop and maintain dashboards that provide consistent and reliable visibility into business performance.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;7949&quot; data-local-id=&quot;e6882314dfc5&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Data Quality &amp;amp; Validation&lt;/strong&gt;&lt;br&gt;Validate data outputs, identify inconsistencies, and support reconciliation efforts across systems (e.g., Salesforce, billing systems).&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;8113&quot; data-local-id=&quot;594e9f3f4184&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Global Collaboration&lt;/strong&gt;&lt;br&gt;Partner with teams across the US and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;EMEA&lt;/span&gt; to deliver timely and high-quality analytics outputs.&lt;/p&gt;
&lt;h4&gt;Qualifications:&lt;/h4&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;2a6f5289-1ba1-42bc-b9e0-e025e63d8f19&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8378&quot; data-local-id=&quot;c34542268462&quot;&gt;Typically requires a minimum of 5 years of related experience in data analytics, business intelligence, or analytics engineering&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8511&quot; data-local-id=&quot;1c806cc03020&quot;&gt;Strong SQL skills and experience working with structured and large datasets&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8590&quot; data-local-id=&quot;cf7e8b23c177&quot;&gt;Experience with modern data tools (e.g., Snowflake, dbt, Looker or similar)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8669&quot; data-local-id=&quot;7e44037ace01&quot;&gt;Experience building and maintaining data models and dashboards&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8735&quot; data-local-id=&quot;7ce21e2da796&quot;&gt;Experience implementing business logic into data transformations&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8803&quot; data-local-id=&quot;75145d80d6d9&quot;&gt;Strong attention to detail and ability to ensure data accuracy&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8869&quot; data-local-id=&quot;e0a6fc5f9d1f&quot;&gt;Ability to work with global teams across time zones&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;8924&quot; data-local-id=&quot;cbedac2c44a5&quot;&gt;Clear communication skills&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;About LaunchDarkly:&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;Modern software delivery was supposed to be the foundation for a thriving digital business but reality has proven otherwise. Slow, inefficient development cycles, costly outages, and fragmented customer experiences are preventing developers from building their best software. The LaunchDarkly platform helps developers innovate on new features faster while protecting them with a safety valve to instantly rewind when things go wrong. Developers can target product experiences to any customer segment and maximize the business impact of every feature. And by gradually rolling out new application components, they escape nightmare &quot;big-bang&quot; technology migrations.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;The LaunchDarkly platform was built to guide engineers to the next frontier of DevOps by:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Improving the velocity and stability of software releases, without the fear of end customer outages&lt;/li&gt;
&lt;li&gt;Delivering targeted experiences by easily personalizing features to customer cohorts&lt;/li&gt;
&lt;li&gt;Maximizing the business impact of every feature through the ability to experiment and optimize&lt;/li&gt;
&lt;li&gt;Coordinating the release and optimization of software to provide consistent experiences across mobile platforms and device types&lt;/li&gt;
&lt;li&gt;Improving the effectiveness and productivity of engineering teams, by providing insights into engineering cadence and stability&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;At LaunchDarkly, we believe in the power of teams. We&#39;re building a team that is humble, open, collaborative, respectful and kind. We are an equal opportunity employer and value diversity at our company. We do not discriminate on the basis of race, religion, color, national origin, gender, gender identity, sexual orientation, age, marital status, veteran status, or disability status. LD invites any applicant to review our written Affirmative Action Plan. To do so, contact People Ops at &lt;span class=&quot;link-annotation-unknown-block-id--893544457&quot;&gt;&lt;a href=&quot;mailto:hr@launchdarkly.com&quot;&gt;hr@launchdarkly.com&lt;/a&gt;&lt;/span&gt;.&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;span class=&quot;s1&quot;&gt;&lt;strong&gt;Do you need a disability accommodation?&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;Fill out this&amp;nbsp;&lt;a href=&quot;https://docs.google.com/forms/d/e/1FAIpQLSdYb_7upYMtdRVXzvXGHGfQw0pU2FNma-6Rwp-I6NjKm7SYNw/viewform&quot;&gt;&lt;span class=&quot;s2&quot;&gt;accommodations request form&lt;/span&gt;&lt;/a&gt;&amp;nbsp;and someone from our People Operations team will contact you for assistance.&amp;nbsp;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;&lt;strong&gt;Your safety matters to us.&lt;/strong&gt; To protect yourself from potential scams, LaunchDarkly recruiters will only contact you from &lt;a href=&quot;https://launchdarkly.slack.com/team/UKEE4GBS6&quot; target=&quot;_blank&quot;&gt;@LaunchDarkly&lt;/a&gt;.com email addresses or via LinkedIn from &quot;Verified Recruiter&quot; accounts.&lt;strong&gt; &lt;/strong&gt;Be cautious of emails from other domains.&amp;nbsp; Legitimate LaunchDarkly recruiters will never ask for money, fees, or banking information before making a job offer. LaunchDarkly will never make a job offer without conducting a formal interview process. Our interview process does not involve asking detailed questions by email. If you are ever unsure about a communication that you receive, don&#39;t click any links—visit &lt;a href=&quot;https://launchdarkly.com/careers/&quot; target=&quot;_blank&quot;&gt;Careers | LaunchDarkly&lt;/a&gt;&amp;nbsp; directly for confirmed job openings and links to apply.&lt;br&gt;&lt;br&gt;Please notify us of any fraudulent representation by sending an email to &lt;a href=&quot;mailto:careers@launchdarkly.com&quot; target=&quot;_blank&quot;&gt;careers@launchdarkly.com&lt;/a&gt;.&lt;/p&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About Mirakl:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Founded in 2012, Mirakl has been at the forefront of marketplace innovation, empowering every business to compete in the platform economy.&lt;br&gt;&lt;br&gt;Today, Mirakl’s operating system combines an enterprise marketplace solution (Mirakl Platform) that enables retailers and B2B organizations to launch, scale, and operate marketplaces and dropship, AI-powered multichannel selling (Mirakl Connect), retail media (Mirakl Ads) and an agentic commerce infrastructure (Mirakl Nexus).&lt;br&gt;&lt;br&gt;With dual headquarters in Boston and Paris, Mirakl helps a global ecosystem of 450+ marketplaces (B2C and B2B) and a network of over 100k third-party marketplace sellers. Brands like Macy’s, Decathlon, Carrefour, Asos, and Airbus Helicopters use Mirakl to grow their businesses in new and remarkable ways.&lt;/p&gt;
&lt;p&gt;For more information: &lt;a href=&quot;http://www.mirakl.com&quot;&gt;www.mirakl.com&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Mirakl in Numbers:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;🗓️ Founded in 2012 | Member of French Tech Next40&lt;/li&gt;
&lt;li&gt;👥 750+ employees in 9 offices worldwide: Paris, Barcelona, Bordeaux, Boston, London, Munich, New York, Sydney, Tokyo&lt;/li&gt;
&lt;li&gt;🇫🇷 350+ Mirakl Tech teams members mainly based in France&lt;/li&gt;
&lt;li&gt;⚙️ 5 Saas Solutions&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Our Values:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Working at Mirakl means accelerating your career alongside ambitious, passionate, and supportive colleagues. We&#39;re proud of the diversity of backgrounds, perspectives, and experiences that make our teams unique.&lt;/p&gt;
&lt;p&gt;Our 5 values guide how we collaborate:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;💡&lt;strong&gt; Work Hard Together:&lt;/strong&gt; Teamwork and collaboration are the foundation of our success&lt;/li&gt;
&lt;li&gt;🏆 &lt;strong&gt;Get Things Done: &lt;/strong&gt;&amp;nbsp;We prioritize action and efficiency for impactful results&lt;/li&gt;
&lt;li&gt;🚀 &lt;strong&gt;Go Above &amp;amp; Beyond:&lt;/strong&gt;&amp;nbsp; We tackle challenges proactively and always aim for excellence&lt;/li&gt;
&lt;li&gt;🎓 &lt;strong&gt;Succeed Through Expertise:&lt;/strong&gt; Knowledge sharing and continuous learning are core to our culture&lt;/li&gt;
&lt;li&gt;🤝 &lt;strong&gt;Satisfy &amp;amp; Empower Clients:&lt;/strong&gt; We&#39;re committed to our clients&#39; success&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;h2&gt;&lt;strong&gt;About the job&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Design, build, and scale production-grade AI systems that power the next generation of intelligent commerce.&lt;br&gt;&lt;br&gt;You will work at the intersection of Software Engineering, Machine Learning, and Generative AI to build AI-native products, agentic systems, and platform capabilities used by Mirakl customers and internal teams.&lt;/p&gt;
&lt;p&gt;This is a permanent position (CDI) based in Paris or Bordeaux, with 4 days on-site per week.&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;s-whitespace-pre-wrap s-break-words s-font-normal first:s-pt-0 last:s-pb-0 s-py-1 @md:s-pt-2 @md:s-pb-[10px] @md:s-leading-relaxed s-text-base s-leading-relaxed s-text-foreground dark:s-text-foreground-night&quot;&gt;&lt;strong class=&quot;s-font-semibold s-text-foreground dark:s-text-foreground-night&quot;&gt;Annual gross salary range (package): €55,000 – €65,000&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;s-whitespace-pre-wrap s-break-words s-font-normal first:s-pt-0 last:s-pb-0 s-py-1 @md:s-pt-2 @md:s-pb-[10px] @md:s-leading-relaxed s-text-base s-leading-relaxed s-text-foreground dark:s-text-foreground-night&quot;&gt;This range is provided for transparency purposes and reflects our internal compensation grid for this role level. The final offer will be determined based on your experience, skills, and the scope of responsibilities involved.&lt;/div&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Why Now, Why Mirakl&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Generative AI and AI Agents are fundamentally reshaping commerce software and the way our teams work on a day to day basis.&lt;/p&gt;
&lt;p&gt;At Mirakl, AI is becoming a core part of our product strategy. From Catalog Transformer and content generation to AI Agents and Agentic Commerce, we are building the next generation of commerce software. And we have the same ambition for our teams around AI products and adoption.&lt;/p&gt;
&lt;p&gt;We are looking for a Senior AI Engineer to transform the way our internal teams work, and to have a significant impact on the agentic side of our Saas products.&lt;/p&gt;
&lt;p&gt;You won&#39;t be joining a company that&#39;s thinking about AI. You&#39;ll be joining one that&#39;s already building it.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;&lt;br&gt;What You’ll Do&lt;/strong&gt;&lt;/h2&gt;
&lt;h4&gt;&lt;strong&gt;1. Design &amp;amp; Build AI Systems&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Design, build, and deploy production-grade AI systems for both Mirakl internal operations.&lt;/li&gt;
&lt;li&gt;Develop solutions leveraging: LLMs, RAG, AI Agents, Multimodal AI and Evaluation frameworks.&lt;/li&gt;
&lt;li&gt;Architect complex agentic workflows including tools, memory, retrieval, planning, and guardrails.&lt;/li&gt;
&lt;li&gt;Rapidly prototype new capabilities and evolve them into scalable, reliable AI production systems.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2. Integrate Across the Stack&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Connect AI systems to internal platforms, business applications, and data sources across the company.&lt;/li&gt;
&lt;li&gt;Enable AI agents to interact with systems such as CRM, data platform, Drive, Jira, support tools, and internal knowledge bases.&lt;/li&gt;
&lt;li&gt;Design robust orchestration layers between models, APIs, tools, retrieval systems, and business workflows.&lt;/li&gt;
&lt;li&gt;Ensure reliability, observability, scalability, and maintainability across the entire AI stack.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;3. Iterate for Impact&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partner with end users, business teams, Product Managers, and Engineers to identify high-value opportunities for AI.&lt;/li&gt;
&lt;li&gt;Run pilots and experiments, gather qualitative and quantitative feedback, and measure business impact.&lt;/li&gt;
&lt;li&gt;Analyze usage patterns, failure modes, costs, latency, and performance metrics.&lt;/li&gt;
&lt;li&gt;Continuously improve accuracy, reliability, adoption, and user experience through data-driven iteration.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;4. Ensure Quality, Security &amp;amp; Reliability&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Implement evaluation frameworks, guardrails, validation layers, and monitoring systems.&lt;/li&gt;
&lt;li&gt;Design AI systems that are secure, explainable, and production-ready.&lt;/li&gt;
&lt;li&gt;Ensure compliance with data security, governance, and access control requirements.&lt;/li&gt;
&lt;li&gt;Document architectures, capabilities, limitations, KPIs, and operational best practices.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;5. Drive Adoption &amp;amp; Enablement&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Build a scalable ecosystem of AI systems and agents that empower both internal teams and customers.&lt;/li&gt;
&lt;li&gt;Support teams in adopting AI-powered workflows and integrating AI into their daily operations.&lt;/li&gt;
&lt;li&gt;Contribute to AI engineering standards, reusable frameworks, and best practices across the company.&lt;/li&gt;
&lt;li&gt;Act as a champion for AI-driven ways of working and help shape Mirakl&#39;s transition toward Agentic Commerce.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Our stack and tools&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Languages: &lt;/strong&gt;Python and SQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;AI Stack:&amp;nbsp;&lt;/strong&gt;OpenAI, Anthropic, Gemini, Mistral and Open-source models&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Agentic &amp;amp; Retrieval: &lt;/strong&gt;LangGraph, LangChain, LlamaIndex, MCP and Vector Databases&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Infrastructure: &lt;/strong&gt;AWS or GCP, Docker and Kubernetes&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;What Makes You Successful&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Strong engineering mindset: able to design reliable and scalable systems&lt;/li&gt;
&lt;li&gt;Strong AI expertise: able to translate the latest AI capabilities into production products&lt;/li&gt;
&lt;li&gt;Strong product mindset: able to balance technical excellence with business impact&lt;/li&gt;
&lt;li&gt;Focus on measurable outcomes, not technical complexity&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Success Metrics&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Product adoption and business impact&lt;/li&gt;
&lt;li&gt;Performance and reliability of AI systems&lt;/li&gt;
&lt;li&gt;Quality of AI outputs and evaluation metrics&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;You&#39;ll Love This Job If you have&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;3+ years of experience in Software Engineering, ML Engineering, Applied AI, or related fields&lt;/li&gt;
&lt;li&gt;Strong Python and software engineering fundamentals&lt;/li&gt;
&lt;li&gt;Hands-on experience building production AI systems using LLMs, RAG, and AI Agents&lt;/li&gt;
&lt;li&gt;Experience designing multi-step agentic workflows and retrieval systems&lt;/li&gt;
&lt;li&gt;Experience evaluating AI systems and improving model performance&lt;/li&gt;
&lt;li&gt;Experience deploying and operating production services in cloud environments&lt;/li&gt;
&lt;li&gt;Strong communication skills in English&lt;/li&gt;
&lt;li&gt;Curiosity, pragmatism, and passion for building AI products&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Feel free to add a link to your GitHub in your CV so we can understand what you have worked on!&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Want to join us? Here is our process&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;A 30-40 min phone conversation with one of our Tech recruiters. This will be an opportunity to discuss your background, expectations, and discover what Mirakl can offer you in return.&lt;/li&gt;
&lt;li&gt;An initial 1 hour technical discussion with a member of the Data Science team and Engineering Team, which will allow you to delve into the more specific aspects of your expertise and discover how your skills can be integrated into our projects.&lt;/li&gt;
&lt;li&gt;2 x 45-minute &quot;STAR&quot; interviews with future Mirakl colleagues to discuss our values and company culture.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;We welcome collaborators with their diverse perspectives and experiences to power us forward. These often far exceed conventional job requirements and help us create a culture of continuous learning. If you’re ready to join a global leader powering digital transformation for 450+ of the world’s most innovative retailers and B2B organizations.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;As part of our recruitment process, Mirakl processes your personal data to review and manage your application and, where appropriate, to consider your profile for future opportunities. You can exercise your data protection rights at any time, and as further detailed in our policies. For more information about how we process your personal data and your rights, please consult our Recruitment Privacy Notice, &lt;a href=&quot;https://www.mirakl.com/recruitment-privacy-notice&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt; in English and &lt;a href=&quot;https://www.mirakl.com/fr-FR/recruitment-privacy-notice&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt; in French.&amp;nbsp;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We may use Artificial Intelligence (AI) solutions to help streamline our hiring process, including screening applications, analyzing resumes, and assessing responses. While AI helps us work efficiently, all final hiring decisions are made by humans. For more information, visit our &lt;/em&gt;&lt;a href=&quot;https://info.mirakl.com/ai-guidelines-for-candidates-and-interviews&quot; target=&quot;_blank&quot;&gt;&lt;em&gt;AI Guidelines for Candidates and Interviews&lt;/em&gt;&lt;/a&gt;&lt;em&gt;.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Ready to do the most impactful work of your career? At&amp;nbsp;&lt;a href=&quot;https://www.coinbase.com/?utm_campaign=mt_o_m_w_m_m__coi_0_jd-onchain&amp;amp;utm_source=coinbase&quot;&gt;Coinbase&lt;/a&gt;, we are uncompromising on our mission to increase economic freedom. The bar is high, the environment is intense, and we like it that way. This isn&#39;t a place for complacency, it’s a place to be pushed past your perceived limits. If you&#39;re ready to build the future of finance alongside people who refuse to settle for &quot;good enough,&quot; you belong here. Coinbase is a remote-first, but not remote-only company. Expect to get together quarterly for intense in-person working sessions called “surges.”&amp;nbsp;&lt;a href=&quot;https://www.coinbase.com/careers&quot;&gt;learn more about working at Coinbase&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;We&#39;re hiring a &lt;strong&gt;Group Product Manager&lt;/strong&gt; to lead the Compliance Agent Experience product team within our EAA organization. This team builds the internal tooling and AI-powered investigation experiences used by Compliance Operations to execute Coinbase&#39;s financial crime programs, including AML Transaction Monitoring, KYC, Enhanced Due Diligence, and Sanctions/Screening. You&#39;ll own the automation-first roadmap that enables investigators to triage alerts, assess risk, and document decisions faster and more accurately, so humans focus on high-judgment work while the platform handles repeatable tasks at scale.&lt;/p&gt;
&lt;p class=&quot;mb-2 whitespace-pre-wrap&quot;&gt;&lt;strong&gt;What you&#39;ll do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own the Compliance Agent Experience product area end-to-end, from vision and strategy through execution, covering AML/TMS, KYC, EDD, and Sanctions/Screening investigation surfaces.&lt;/li&gt;
&lt;li&gt;Drive a multi-year roadmap for AI-assisted, human-in-the-loop investigation workflows that measurably reduce cycle time, improve decision quality, and increase automation adoption.&lt;/li&gt;
&lt;li&gt;Lead build-vs-buy and vendor strategy for investigation enablement (OSINT, case enrichment, LLM tooling), including evaluations and RFPs in partnership with Compliance, Legal, Security, and Procurement.&lt;/li&gt;
&lt;li&gt;Partner with Engineering, Data Science/ML, Compliance Program owners, and CX Operations to deliver integrated tooling that reduces context-switching and improves end-to-end investigation throughput.&lt;/li&gt;
&lt;li&gt;Establish success metrics and instrumentation for Compliance tooling (investigation cycle time, AHT, escalation rates, QA outcomes, false positive reduction, automation adoption) and report progress to executive stakeholders through regular business reviews.&lt;/li&gt;
&lt;li&gt;Shape security, privacy, and auditability requirements, including access controls, data retention, audit trails, and model governance, ensuring regulatory readiness without compromising investigator usability.&lt;/li&gt;
&lt;/ul&gt;
&lt;p class=&quot;mb-2 whitespace-pre-wrap&quot;&gt;&lt;strong&gt;Required Skills and Experience:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;10+ years of product management experience, including 5+ years leading and developing PM teams, with a track record of shipping internal tooling or operational platforms at global scale.&lt;/li&gt;
&lt;li&gt;Demonstrated experience building AI/ML-powered automation or workflow products (e.g., LLM-based assistants, human-in-the-loop decisioning, intelligent case routing) in compliance, fintech, or similarly regulated domains.&lt;/li&gt;
&lt;li&gt;Deep familiarity with AML, transaction monitoring, investigations, sanctions screening, or KYC/EDD operations, including auditability and regulator-facing requirements.&lt;/li&gt;
&lt;li&gt;Proven ability to define measurable outcomes (throughput, quality, automation rates), instrument product surfaces, and use data to drive roadmap prioritization across a multi-team portfolio.&lt;/li&gt;
&lt;li&gt;Track record of leading cross-functional programs spanning engineering, compliance, data science, and operations with 5+ teams, and communicating strategy and tradeoffs to VP+ audiences.&lt;/li&gt;
&lt;li&gt;Utilizes generative AI responsibly, maintaining human oversight to deliver business-ready outputs and drive measurable improvements in workflow efficiency, cost, and quality.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;strong&gt;Pay Transparency Notice:&lt;/strong&gt;&lt;strong&gt;&lt;em&gt; &lt;/em&gt;&lt;/strong&gt;Base salary varies by location (see range below). Total compensation may also include equity and bonus eligibility, and benefits (medical, dental, vision, 401(k)).&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Annual base salary range (excluding equity and bonus):&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$243,865&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$286,900 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;ul&gt;
&lt;li style=&quot;font-style: italic; font-size: 8pt;&quot;&gt;&lt;strong&gt;&lt;em&gt;Application Limit: &lt;/em&gt;&lt;/strong&gt;Candidates may submit a maximum of 3 applications within a 6-month period.&lt;/li&gt;
&lt;li style=&quot;font-style: italic; font-size: 8pt;&quot;&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;&lt;em&gt;&lt;strong&gt;Equal Opportunity Employer: &lt;/strong&gt;Coinbase is an Equal Opportunity Employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, sexual orientation, gender identity, national origin, disability, protected veteran status, or genetic information. Applicants with criminal histories will be considered consistent with applicable federal, state, and local laws.&lt;/em&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic; font-size: 8pt;&quot;&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;&lt;em&gt;&lt;strong&gt;US Applicants: &lt;/strong&gt;View&lt;a href=&quot;https://www.dol.gov/sites/dolgov/files/WHD/legacy/files/eppac.pdf&quot;&gt; Employee Rights&lt;/a&gt;,&lt;a href=&quot;https://www.eeoc.gov/sites/default/files/2023-06/22-088_EEOC_KnowYourRights6.12.pdf&quot;&gt; Know Your Rights&lt;/a&gt;, and&lt;a href=&quot;https://static-assets.coinbase.com/e-verify.pdf&quot;&gt; E-Verify&lt;/a&gt; Notice of Participation.&lt;/em&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic; font-size: 8pt;&quot;&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;&lt;em&gt;&lt;strong&gt;Accommodations: &lt;/strong&gt;If you are an individual with a disability who needs a reasonable accommodation, email us your request and contact info at accommodations[at]coinbase.com.&amp;nbsp;Need screen reading technology?&lt;a href=&quot;https://chromewebstore.google.com/detail/screen-reader/kgejglhpjiefppelpmljglcjbhoiplfn&quot;&gt; Click here&lt;/a&gt; to download a free compatible screen reader and view the&lt;a href=&quot;http://www.chromevox.com/tutorial/&quot;&gt;&lt;strong&gt; &lt;/strong&gt;tutorial&lt;/a&gt;.&lt;/em&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic; font-size: 8pt;&quot;&gt;&lt;span style=&quot;font-size: 8pt;&quot;&gt;&lt;em&gt;&lt;strong&gt;Data Privacy &amp;amp; Arbitration: &lt;/strong&gt;By submitting your application, you agree to our&lt;a href=&quot;https://www.coinbase.com/legal/applicant_privacy_notice&quot;&gt; Candidate Privacy Notice&lt;/a&gt;. US applicants: By submitting your application, you agree to&lt;a href=&quot;https://www.coinbase.com/legal/application-arbitration-agreement&quot;&gt; Arbitration of Disputes&lt;/a&gt;.&lt;br&gt;&lt;/em&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
